insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 165, 'ആദ്യമായി വസ്ത്രം ധരിപ്പിക്കപ്പെടുന്നവൻ', null, 897 from books where volume_id=1 and book_no=31 on conflict (book_id, chapter_no) do nothing;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَمَّنِي جِبْرِيلُ عَلَيْهِ السَّلَام عِنْدَ الْبَيْتِ مَرَّتَيْنِ: فَصَلَّى الظُّهْرَ فِي الْأُولَى مِنْهُمَا حِينَ كَانَ الْفَيْءُ مِثْلَ الشِّرَاكِ، ثُمَّ صَلَّى الْعَصْرَ حِينَ كَانَ ظِلُّ كُلُّ شَيْءٍ مِثْلَ ظِلِّهِ، ثُمَّ صَلَّى الْمَغْرِبَ حِينَ وَغَرُبَتِ الشَّمْسُ وَأَفْطَرَ الصَّائِمُ، ثُمَّ صَلَّى الْعِشَاءَ حِينَ غَابَ الشَّفَقُ، ثُمَّ صَلَّى الْفَجْرَ حِينَ بَرَقَ الْفَجْرُ وَحَرُمَ الطَّعَامُ عَلَى الصَّائِمِ، وَصَلَّى الْمَرَّةَ الثَّانِيَةَ الظُّهْرَ حِينَ كَانَ ظِلُّ كُلُّ شَيْءٍ مِثْلَهُ لِوَقْتِ الْعَصْرِ بِالْأَمْسِ، ثُمَّ صَلَّى الْعَصْرَ حِينَ كَانَ ظِلُّ كُلُّ شَيْءٍ مِثْلَيْهِ، ثُمَّ صَلَّى الْمَغْرِبَ لِوَقْتِهِ الْأَوَّلِ، ثُمَّ صَلَّى الْعِشَاءَ الْآخِرَةَ حِينَ ذَهَبَ ثُلُثُ اللَّيْلِ، ثُمَّ صَلَّى الصُّبْحَ حِينَ أَسْفَرَتِ الْأَرْضُ. ثُمَّ الْتَفَتَ إِلَيَّ جِبْرِيلُ فَقَالَ: يَا مُحَمَّدُ! هَذَا وَقْتُ الْأَنْبِيَاءِ مِنْ قَبْلِكَ، وَالْوَقْتُ فِيمَا بَيْنَ هَذَيْنِ الْوَقْتَيْنِ". (د,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "കഅ്ബയുടെ അടുത്തു വെച്ച് ജിബ്രീൽ(അ) രണ്ടു പ്രാവശ്യം എനിക്കു ഇമാമായി നിസ്കരിച്ചു. അതിൽ ഒന്നാം പ്രാവശ്യം നിഴൽ ചെരുപ്പിന്റെ വള്ളി പോലെയായിരുന്നപ്പോൾ ളുഹർ നിസ്കരിച്ചു.¹ പിന്നെ ഓരോ വസ്തുവിന്റെയും നിഴൽ അതിനോളം എത്തിയപ്പോൾ അസ്ർ നിസ്കരിച്ചു. പിന്നീട് സൂര്യൻ അസ്തമിക്കുകയും നോമ്പുകാരൻ നോമ്പു മുറിക്കുകയും ചെയ്ത(സമയമായ)പ്പോൾ മഗ്‌രിബ് നിസ്കരിച്ചു. ആകാശത്തിലെ ശോഭ മാഞ്ഞപ്പോൾ ഇശാഅ് നിസ്കരിച്ചു. പ്രഭാതം വിടരുകയും നോമ്പുകാരന് ഭക്ഷണം നിഷിദ്ധമാവുകയും ചെയ്തപ്പോൾ ഫജ്ർ നിസ്കരിച്ചു. രണ്ടാം പ്രാവശ്യം വസ്തുക്കളുടെ നിഴൽ അതിനോളമെത്തിയപ്പോൾ - കഴിഞ്ഞ ദിവസത്തെ അസ്റിന്റെ സമയത്ത് - ളുഹ്ർ നിസ്കരിച്ചു. വസ്തുവിന്റെ നിഴൽ അതിന്റെ ഇരട്ടിയായപ്പോൾ അസ്ർ നിസ്കരിച്ചു. മഗ്‌രിബ് അതിന്റെ സമയത്തിന്റെ തുടക്കത്തിൽ തന്നെ നിർവഹിച്ചു. രാത്രിയുടെ മൂന്നിലൊന്ന് കഴിഞ്ഞപ്പോൾ ഇശാ നിർവഹിച്ചു. ഭൂമി വർണ്ണമണിഞ്ഞപ്പോഴാണ് സുബ്ഹി നിസ്കരിച്ചത്. പിന്നീട് ജ്ബ്രീൽ(അ) എന്റെ നേരെ തിരിഞ്ഞ് പറഞ്ഞു: മുഹമ്മദ്! ഇതാണ് താങ്കൾക്ക് മുമ്പുള്ള പ്രവാചകന്മാരുടെ സമയം. നിസ്കാര സമയം ഇതിന് രണ്ടിനുമിടയിലാണ്." (ദ,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', '¹. മദ്ധ്യത്തിൽ നിന്ന് ഒരടി നീങ്ങിയപ്പോൾ.', null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 317, 317, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ فَسَأَلَهُ عَنْ مَوَاقِيتِ الصَّلَاةِ فَقَالَ: "أَقِمْ مَعَنَا إِنْ شَاءَ اللهُ". فَأَمَرَ بِلَالًا، فَأَقَامَ حِينَ طَلَعَ الْفَجْرُ، ثُمَّ أَمَرَهُ فَأَقَامَ حِينَ زَالَتِ الشَّمْسُ، فَصَلَّى الظُّهْرَ، ثُمَّ أَمَرَهُ فَأَقَامَ فَصَلَّى الْعَصْرَ وَالشَّمْسُ بَيْضَاءُ مُرْتَفِعَةٌ، ثُمَّ أَمَرَهُ بِالْمَغْرِبِ حِينَ وَقَعَ حَاجِبُ الشَّمْسِ، ثُمَّ أَمَرَهُ بِالْعِشَاءِ فَأَقَامَ حِينَ غَابَ الشَّفَقُ، ثُمَّ أَمَرَهُ مِنَ الْغَدِ فَنَوَّرَ بِالْفَجْرِ، ثُمَّ أَمَرَهُ بِالظُّهْرِ فَأَبْرَدَ وَأَنْعَمَ أَنْ يُبْرِدَ، ثُمَّ أَمَرَهُ بِالْعَصْرِ فَأَقَامَ وَالشَّمْسُ آخِرَ وَقْتِهَا فَوْقَ مَا كَانَتْ، ثُمَّ أَمَرَهُ فَأَخَّرَ الْمَغْرِبَ إِلَى قُبَيْلِ أَنْ يَغِيبَ الشَّفَقُ، ثُمَّ أَمَرَهُ بِالْعِشَاءِ فَأَقَامَ حِينَ ذَهَبَ ثُلُثُ اللَّيْلِ، ثُمَّ قَالَ: "أَيْنَ السَّائِلُ عَنْ مَوَاقِيتِ الصَّلَاةِ؟" فَقَالَ الرَّجُلُ: أَنَا، فَقَالَ: "مَوَاقِيتُ الصَّلَاةِ كَمَا بَيْنَ هَذَيْنِ". (م,ت,ن,جه)', 'ബുറൈദ(റ): നബി(സ)യുടെ അടുത്ത് ഒരാൾ വന്നു നിസ്കാര സമയങ്ങളെക്കുറിച്ചു ചോദിച്ചു. നബി(സ) പറഞ്ഞു: "ഇൻശാ അല്ലാഹ്! നീ ഞങ്ങളോടൊപ്പം താമസിക്കുക." പ്രഭാതം വിടർന്നപ്പോൾ ബിലാൽ(റ)വിനോട് നബി(സ) കൽപിച്ച പ്രകാരം ബിലാൽ(റ) ഇഖാമത്ത് വിളിച്ചു. സൂര്യൻ മദ്ധ്യത്തിൽനിന്ന് തെറ്റിയപ്പോൾ വീണ്ടും കൽപന പ്രകാരം ബിലാൽ ഇഖാമത്തു വിളിച്ച് ളുഹ്ർ നിസ്കരിച്ചു. സൂര്യൻ ഉയർന്നു വെള്ള ശോഭയുള്ളതായിരിക്കെ ഇഖാമത്ത് വിളിക്കാൻ പറയുകയും നബി(സ) അസ്ർ നിസ്കരിക്കുകയും ചെയ്തു. സൂര്യൻ മറയിട്ടപ്പോൾ മഗ്‌രിബിന് ഇഖാമത്ത് വിളിക്കാൻ കൽപിച്ചു. മാനത്തെ ചുവപ്പ് നിറം മറഞ്ഞപ്പോൾ ഇശാഇനുള്ള ഇഖാമത്ത് വിളിക്കാൻ കൽപിച്ചു. പിറ്റേദിവസം പ്രഭാതം പ്രകാശം പരന്നപ്പോൾ ഫജ്റിന് ഇഖാമത്ത് വിളിക്കാൻ കൽപിച്ചു. പിന്നീട് സൂര്യന്റെ ചൂട് നന്നായി കുറഞ്ഞപ്പോൾ ളുഹ്ർ നിസ്കാരത്തിന് കൽപിച്ചു. സൂര്യൻ അതിന്റെ അവസാനത്തിലെത്തിയപ്പോൾ അസ്റിന് കൽപിച്ചു. മാനത്തെ ചുവപ്പ് മായുന്നതിന് അൽപം മുമ്പുവരെ മഗ്‌രിബ് പിന്തിക്കുകയും ഇഖാമത്ത് വിളിക്കാൻ കൽപിക്കുകയും ചെയ്തു. രാത്രിയുടെ മൂന്നിലൊന്നു കഴിഞ്ഞപ്പോൾ ഇശാഇന് കൽപിക്കുകയും ഇഖാമത്ത് വിളിക്കുകയും ചെയ്തു. പിന്നെ ചോദിച്ചു: "നിസ്കാര സമയത്തെക്കുറിച്ച് അന്വേഷിച്ച ആളെവിടെ?" ഞാനിവിടെയുണ്ട് എന്ന് അയാൾ പറഞ്ഞു. തിരുമേനി(സ) പറഞ്ഞു: "നിസ്കാരത്തിന്റെ സമയങ്ങൾ ഇവരണ്ടിനും ഇടയിലാണ്". (മു,തു,ന,ജ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['م','ت','ن','جه']::text[], array['മു','തു','ന','ജ']::text[], null, null, 317, 318, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنِ ابْنِ شِهَابٍ رَضِيَ اللهُ عَنْهُ: أَنَّ عُمَرَ بْنَ عَبْدِ الْعَزِيزِ كَانَ قَاعِدًا عَلَى الْمِنْبَرِ، فَأَخَّرَ الْعَصْرَ شَيْئًا، فَقَالَ لَهُ عُرْوَةُ بْنُ الزُّبَيْرِ: أَمَا إِنَّ جِبْرِيلَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَدْ أَخْبَرَ مُحَمَّدًا صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِوَقْتِ الصَّلَاةِ. فَقَالَ لَهُ عُمَرُ: اعْلَمْ مَا تَقُولُ. فَقَالَ عُرْوَةُ: سَمِعْتُ بَشِيرَ بْنَ أَبِي مَسْعُودٍ يَقُولُ: سَمِعْتُ أَبَا مَسْعُودٍ الْأَنْصَارِيَّ يَقُولُ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "نَزَلَ جِبْرِيلُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَنِي بِوَقْتِ الصَّلَاةِ: فَصَلَّيْتُ مَعَهُ، ثُمَّ صَلَّيْتُ مَعَهُ، ثُمَّ صَلَّيْتُ مَعَهُ، ثُمَّ صَلَّيْتُ مَعَهُ". يَحْسُبُ بِأَصَابِعِهِ خَمْسَ صَلَوَاتٍ. فَرَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى الظُّهْرَ حِينَ تَزُولُ الشَّمْسُ، وَرُبَّمَا أَخَّرَهَا حِينَ يَشْتَدُّ الْحَرُّ، وَرَأَيْتُهُ يُصَلِّي الْعَصْرَ وَالشَّمْسُ مُرْتَفِعَةٌ بَيْضَاءُ قَبْلَ أَنْ تَدْخُلَهَا الصُّفْرَةُ، فَيَنْصَرِفُ الرَّجُلُ مِنَ الصَّلَاةِ فَيَأْتِي ذَا الْحُلَيْفَةِ قَبْلَ غُرُوبِ الشَّمْسِ، وَيُصَلِّي الْمَغْرِبَ حِينَ تَسْقُطُ الشَّمْسُ، وَيُصَلِّي الْعِشَاءَ حِينَ يَسْوَدُّ الْأُفُقُ، وَرُبَّمَا أَخَّرَهَا حَتَّى يَجْتَمِعَ النَّاسُ، وَصَلَّى الصُّبْحَ مَرَّةً بِغَلَسٍ، ثُمَّ صَلَّى مَرَّةً أُخْرَى فَأَسْفَرَ بِهَا، ثُمَّ كَانَتْ صَلَاتُهُ بَعْدَ ذَلِكَ التَّغْلِيسَ حَتَّى مَاتَ، وَلَمْ يَعُدْ إِلَى أَنْ يُسْفِرَ. (خ,د,ن,جه)', 'ഇബ്നുശിഹാബ്(റ): ഉമറുബ്നു അബ്ദിൽ അസീസ്(റ) ഒരിക്കൽ മിമ്പറിൽ ഇരിക്കുകയായിരുന്നു. അദ്ദേഹം അസ്റിനെ അൽപം പിന്തിച്ചു. അപ്പോൾ ഉർവത്തുബ്നു സുബൈർ(റ) അദ്ദേഹത്തോടു പറഞ്ഞു: ജിബ്രീൽ(അ) മുഹമ്മദി(സ)നെ നിസ്കാരത്തിന്റെ സമയം അറിയിച്ചിട്ടുണ്ടല്ലോ? അപ്പോൾ ഉമർ(റ) അദ്ദേഹത്തോട് പറഞ്ഞു: താങ്കൾ പറഞ്ഞതിനെക്കുറിച്ചു എനിക്കറിയാം. അപ്പോൾ ഉർവ(റ) പറഞ്ഞു: നബി(സ) പറയുന്നത് കേട്ടതായി അബൂമസ്ഊദ്(റ)വിൽ നിന്നും ബശീറുബ്നു അബീമസ്ഊദ്(റ) ഇപ്രകാരം ഉദ്ധരിക്കുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: നബി(സ) പറഞ്ഞു: "ജിബ്രീൽ(അ) ഇറങ്ങിവന്ന് നിസ്കാര സമയങ്ങൾ എനിക്കറിയിച്ചു തന്നു. ഞാൻ ജിബ്രീൽ(അ)മിന്റെ കൂടെ നിസ്കരിച്ചു. വീണ്ടും അദ്ദേഹത്തോടൊപ്പം നിസ്കരിച്ചു. വീണ്ടും അദ്ദേഹത്തോടൊപ്പം നിസ്കരിച്ചു. വീണ്ടും അദ്ദേഹത്തോടൊപ്പം നിസ്കരിച്ചു. വീണ്ടും അദ്ദേഹത്തോടൊപ്പം നിസ്കരിച്ചു." വിരലിൽ എണ്ണിക്കൊണ്ട് അഞ്ച് നേരത്തെ നിസ്കാരമാണ് നബി(സ) സൂചിപ്പിച്ചത്. സൂര്യൻ ആകാശ മധ്യത്തിൽനിന്നൽപം തെറ്റിയപ്പോൾ നബി(സ) ളുഹ്ർ നിസ്കരിക്കുന്നത് ഞാൻ കണ്ടു. ചൂട് കഠിനമാകുമ്പോൾ ളുഹ്ർ പിന്തിക്കാറുണ്ട്. സൂര്യൻ ഉയർന്നുനിൽക്കെ മഞ്ഞ നിറം ഉണ്ടാകുന്നതിനുമുമ്പ് വെള്ള നിറത്തിൽ ആയിരിക്കെ അസ്ർ നിസ്കരിക്കുന്നതും ഞാൻ കണ്ടിട്ടുണ്ട്. നിസ്കാരം കഴിഞ്ഞശേഷം സൂര്യാസ്തമനത്തിനു മുമ്പുതന്നെ ഒരാൾക്ക് ദുൽഹുലൈഫ എന്ന സ്ഥലത്ത് എത്തിച്ചേരാമായിരുന്നു. സൂര്യൻ അസ്തമിച്ചശേഷം നബി(സ) മഗ്‌രിബ് നിസ്ക്കരിക്കും. ചക്രവാളം കറുത്തിരുളുമ്പോൾ അദ്ദേഹം ഇശാ നിസ്കരിക്കും. ചിലപ്പോൾ ആളുകൾ ഒരുമിച്ചു കൂടുന്നതുവരെ ഇശാ പിന്തിക്കാറുണ്ട്. ഒരു പ്രാവശ്യം സുബ്ഹ് ഇരുട്ടുള്ളപ്പോഴും മറ്റൊരു പ്രാവശ്യം നേരം പുലർന്നശേഷവും നിസ്കരിച്ചു. പിന്നീട് തിരുമേനി(സ)യുടെ വിയോഗം വരെ ഇരുട്ടുള്ളപ്പോഴായിരുന്നു സുബ്ഹ് നിസ്കരിച്ചിരുന്നത്. നേരം പുലർന്നശേഷം നിസ്കരിക്കുന്നത് ആവർത്തിച്ചിട്ടില്ല. (ബു,ദ,ന,ജ)', 'ابْنِ شِهَابٍ', 'ഇബ്നുശിഹാബ്(റ)', null, null, array['خ','د','ن','جه']::text[], array['ബു','ദ','ന','ജ']::text[], null, null, 318, 319, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "وَقْتُ الظُّهْرِ مَا لَمْ تَحْضُرِ الْعَصْرُ، وَوَقْتُ الْعَصْرِ مَا لَمْ تَصْفَرَّ الشَّمْسُ، وَوَقْتُ الْمَغْرِبِ مَا لَمْ يَسْقُطْ فَوْرُ الشَّفَقِ، وَوَقْتُ الْعِشَاءِ إِلَى نِصْفِ اللَّيْلِ، وَوَقْتُ صَلَاةِ الْفَجْرِ مَا لَمْ تَطْلُعِ الشَّمْسُ". (م,د,ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "അസ്ർ ആകുന്നതു വരെയാണ് ളുഹ്റിന്റെ സമയം. സൂര്യൻ മഞ്ഞ വർണ്ണമാകുംവരെയാണ് അസ്റിന്റെ സമയം. മാനത്തെ ചുവപ്പ് മായാതിരിക്കുന്നതുവരെയാണ് മഗ്‌രിബിന്റെ സമയം. രാത്രിയുടെ പകുതി വരെയാണ് ഇശാഇന്റെ സമയം. സൂര്യൻ ഉദിക്കാതിരിക്കുവോളം ഫജ്റിന്റെ സമയമാണ്. (മു,ദ,ന)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 319, 319, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ أَنَّ رَسُولَ اللهِ صَلَّى اللهم عَلَيْهِ وَسَلَّمَ غَزَا خَيْبَرَ فَصَلَّيْنَا عِنْدَهَا صَلَاةَ الْغَدَاةِ بِغَلَسٍ، فَرَكِبَ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَرَكِبَ أَبُو طَلْحَةَ وَأَنَا رَدِيفُ أَبِي طَلْحَةَ فَأَجْرَى نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي زُقَاقِ خَيْبَرَ وَإِنَّ رُكْبَتِي لَتَمَسُّ فَخِذَ نَبِيِّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثُمَّ حَسَرَ الْإِزَارَ عَنْ فَخِذِهِ حَتَّى إِنِّي أَنْظُرُ إِلَى بَيَاضِ فَخِذِ نَبِيِّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَلَمَّا دَخَلَ الْقَرْيَةَ، قَالَ: اللهُ أَكْبَرُ، خَرِبَتْ خَيْبَرُ، إِنَّا إِذَا نَزَلْنَا بِسَاحَةِ قَوْمٍ فَسَاءَ صَبَاحُ الْمُنْذَرِينَ، قَالَهَا ثَلَاثًا، قَالَ: وَخَرَجَ الْقَوْمُ إِلَى أَعْمَالِهِمْ فَقَالُوا مُحَمَّدٌ قَالَ عَبْدُالْعَزِيزِ وَقَالَ بَعْضُ أَصْحَابِنَا وَالْخَمِيسُ يَعْنِي الْجَيْشَ، قَالَ: فَأَصَبْنَاهَا عَنْوَةً فَجُمِعَ السَّبْيُ فَجَاءَ دِحْيَةُ فَقَالَ يَا نَبِيَّ اللهِ: أَعْطِنِي جَارِيَةً مِنَ السَّبْيِ فَقَالَ: اذْهَبْ فَخُذْ جَارِيَةً، فَأَخَذَ صَفِيَّةَ بِنْتَ حُيَيٍّ فَجَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا نَبِيَّ اللهِ أَعْطَيْتَ دِحْيَةَ صَفِيَّةَ بِنْتَ حُيَيٍّ سَيِّدَةَ قُرَيْظَةَ وَالنَّضِيرِ لَا تَصْلُحُ إِلَّا لَكَ قَالَ: ادْعُوهُ، بِهَا فَجَاءَ بِهَا فَلَمَّا نَظَرَ إِلَيْهَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: خُذْ جَارِيَةً مِنَ السَّبْيِ غَيْرَهَا، قَالَ: فَأَعْتَقَهَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَتَزَوَّجَهَا وَجَعَلَ صَدَاقَهَا عِتْقَهَا، حَتَّى إِذَا كَانَ بِالطَّرِيقِ جَهَّزَتْهَا لَهُ أُمُّ سُلَيْمٍ فَأَهْدَتْهَا لَهُ مِنَ اللَّيْلِ فَأَصْبَحَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَرُوسًا فَقَالَ: مَنْ كَانَ عِنْدَهُ شَيْءٌ فَلْيَجِئْ بِهِ، وَبَسَطَ نِطَعًا، فَجَعَلَ رَجُلٌ يَجِيءُ بِالتَّمْرِ، وَجَعَلَ الرَّجُلُ يَجِيءُ بِالسَّمْنِ قَالَ وَأَحْسِبُهُ قَدْ ذَكَرَ السَّوِيقَ قَالَ: فَحَاسُوا حَيْسًا فَكَانَتْ وَلِيمَةَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (خ)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) ഖൈബർ ആക്രമിച്ച സന്ദർഭത്തിൽ അവിടെ വെച്ച് നേരം പുലരുന്നതിനു മുമ്പ് നേരിയ ഇരുട്ടിൽ ഞങ്ങൾ സുബ്ഹ് നിസ്കരിച്ചു. പ്രവാചകൻ(സ) വാഹനത്തിൽ കയറി, അബൂത്വൽഹ(റ)യും കയറി. ഞാൻ അബുത്വൽഹ(റ)യുടെ പിറകിലായും കയറി. പ്രവാചകൻ(സ) ഖൈബർ പട്ടണത്തിലെ തെരുവുകളിലേക്ക് വാഹനത്തെ നയിച്ചു. എന്റെ കാൽമുട്ട് പ്രവാചക(സ)ന്റെ തുടയിൽമേൽ തട്ടുന്നുണ്ടായിരുന്നു. പ്രവാചകൻ(സ) തന്റെ തുടയിൽനിന്നും വസ്ത്രം അൽപം മാറ്റി. പ്രവാചകന്റെ തുടയുടെ വെളുപ്പ് ഞാൻ കാണുന്നുണ്ടായിരുന്നു. പട്ടണത്തിൽ പ്രവേശിച്ചപ്പോൾ പ്രവാചകൻ(സ) ഇപ്രകാരം പറഞ്ഞു: "അല്ലാഹു അക്ബർ. ഖൈബർ ഇതാ നശിച്ചിരിക്കുന്നു; ഒരു ജനതയുടെ മുറ്റത്ത് നാം ഇറങ്ങിക്കഴിഞ്ഞാൽ ആ താക്കീതു നൽകപ്പെട്ടവരുടെ പ്രഭാതം എത്ര മോശമായിരിക്കും." പ്രവാചകൻ(സ) ഇത് മൂന്ന് തവണ ആവർത്തിച്ചു പറഞ്ഞു. നിവേദകൻ പറയുന്നു: അവിടെയുള്ള നിവാസികൾ അവരുടെ ജോലികൾക്കായി പുറത്തിറങ്ങിയപ്പോൾ ''ഇതാ മുഹമ്മദും പട്ടാളവും'' എന്ന് (അത്ഭുത പരവശരായിക്കൊണ്ട്) പറയാൻ തുടങ്ങി. അനസ്(റ) പറയുന്നു: ശക്തികൊണ്ടാണ് ഞങ്ങൾ ഖൈബർ ജയിച്ചടക്കിയത്. യുദ്ധത്തടവുകാരെയെല്ലാം ഒരു സ്ഥത്ത് ഒരുമിച്ചു കൂട്ടി. അപ്പോൾ ദിഹയത്തുൽ കൽബി(റ) വന്നുകൊണ്ട് പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, ഈ യുദ്ധത്തടവുകാരിൽനിന്നും ഒരു പെൺകുട്ടിയെ എനിക്കു നൽകിയാലും. നബി(സ) പറഞ്ഞു: "നീ പോയി ഒരു പെൺകുട്ടിയെ എടുത്തുകൊള്ളുക." അങ്ങിനെ ഹുയയ്യിന്റെ മകൾ സഫിയ്യ(റ)യെ ആണ് അദ്ദേഹം എടുത്തത്. അപ്പോൾ ഒരാൾ വന്ന് തിരുമേനി(സ)യോട് പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ! ഖുറൈള, നളീർ എന്നി ഗോത്രങ്ങളുടെ നേതൃസ്ഥാനത്തുള്ള സഫിയ്യ(റ)യെ അങ്ങ് ദിഹ്യക്ക് നൽകിയിരിക്കുന്നു. യഥാർത്തത്തിൽ അങ്ങേക്ക് മാത്രം അനുയോജ്യമായവളാണവൾ. തിരുമേനി(സ) പറഞ്ഞു: "ദിഹ്യയെ ഇങ്ങോട്ട വിളിക്കുക!" അപ്പോൾ ദിഹ്യ അവളുമായി വന്നു. തിരുമേനി(സ) അദ്ദേഹത്തോട് പറഞ്ഞു: "നീ യുദ്ധത്തടവുകാരിൽ മറ്റൊരു പെൺകുട്ടിയെ എടുത്തു കൊള്ളുക!" തിരുമേനി(സ) അവളെ യുദ്ധത്തടവിൽനിന്നും മോചിപ്പിക്കുകയും വിവാഹം കഴിക്കുകയും ചെയ്തു. അവളുടെ മോചനം തന്നെയാണ് അവൾക്ക് മഹ്റായി കണക്കാക്കിയത്. യാത്രക്കിടയിൽ തിരുമേനി(സ)ക്കൊപ്പം വീടുകൂടാൻ വേണ്ടി ഉമ്മുസുലൈം(റ) സഫിയ്യ(റ)യെ അണിയിച്ചൊരുക്കി. രാത്രിയായപ്പോൾ ഉമ്മുസുലൈം(റ) തിരുമേനി(സ)ക്ക് സഫിയ്യ(റ)യെ ഏൽപിച്ചുകൊടുത്തു. അങ്ങനെ തിരുമേനി(സ) പ്രഭാത വേളയിൽ നവവരനായി. തിരുമേനി(സ) പറഞ്ഞു: "വല്ലവന്റെയും അടുക്കൽ ആഹാരവസ്തുവായി വല്ലതുമുണ്ടെങ്ങിൽ അവരതു കൊണ്ടുവരട്ടെ!" എന്നിട്ട് തിരുമേനി(സ) തോലിന്റെ ഒരു സുപ്ര വിരിച്ചു. ചിലർ ഈത്തപ്പഴവും മറ്റു ചിലർ നെയ്യും കൊണ്ടുവന്നു. - ''ഗോതമ്പ് കൊണ്ടുവന്നു എന്നും അനസ്(റ) പറഞ്ഞിട്ടുണ്ടെന്നാണ് ഞാൻ വിചാരിക്കുന്നത്'' എന്ന് ഹദീസ് റിപ്പോർട്ടർ പറയുന്നു: എന്നിട്ട് അവയെല്ലാം കൂടി അവർ കൂട്ടിക്കലർത്തി. അതായിരുന്നു തിരുമേനി(സ)യുടെ വിവാഹസദ്യ. (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 319, 320, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ أَبِي بَرْزَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الظُّهْرَ إِذَا زَالَتِ الشَّمْسُ، وَيُصَلِّي الْعَصْرَ وَإِنَّ أَحَدَنَا لَيَذْهَبُ إِلَى أَقْصَى الْمَدِينَةِ وَيَرْجِعُ وَالشَّمْسُ حَيَّةٌ، وَنَسِيتُ الْمَغْرِبَ، وَكَانَ لَا يُبَالِي تَأْخِيرَ الْعِشَاءِ إِلَى ثُلُثِ اللَّيْلِ، قَالَ: ثُمَّ قَالَ: إِلَى شَطْرِ اللَّيْلِ، قَالَ: وَكَانَ يَكْرَهُ النَّوْمَ قَبْلَهَا وَالْحَدِيثَ بَعْدَهَا، وَكَانَ يُصَلِّي الصُّبْحَ وَمَا يَعْرِفُ أَحَدُنَا جَلِيسَهُ الَّذِي كَانَ يَعْرِفُهُ، وَكَانَ يَقْرَأُ فِيهَا مِنَ السِّتِّينَ إِلَى الْمِائَةِ". (ق,د,ن,جه)', 'അബൂബർസ(റ): സൂര്യൻ ആകാശ മധ്യത്തിൽനിന്ന് തെറ്റിയപ്പോഴാണ് നബി(സ) ളുഹ്ർ നിസ്കരിച്ചിരുന്നത്. ഞങ്ങളിലൊരാൾ മദീനയുടെ അറ്റം വരെ പോയി തിരിച്ചു വന്നാലും സൂര്യൻ അസ്തമിക്കാതെ ജീവസുറ്റ് കിടക്കും. ആ സമയത്താണ് അസ്ർ നിസ്കരിച്ചിരുന്നത്. മഗ്‌രിബിന്റെ സമയം ഞാൻ മറന്നുപോയി. രാത്രിയുടെ മൂന്നിലൊന്നു വരെ ഇശാ പിന്തിക്കുന്നതിൽ വിമുഖത കാണിച്ചിരുന്നില്ല. - പിന്നെ അദ്ദേഹം രാത്രിയുടെ പകുതിവരെ എന്നും പറഞ്ഞു - ഇശാഇനു ശേഷം സംസാരിക്കുന്നതും അതിന്നു മുമ്പ് ഉറങ്ങുന്നതും നബി(സ) ഇഷ്ടപ്പെട്ടിരുന്നില്ല. സുബ്ഹ് നിസ്കരിച്ചിരുന്നത് ഒരാൾ തനിക്കറിയാവുന്ന പരിചയക്കാരനെ പോലും തിരിച്ചറിയാത്തത്ര നേരത്തെയായിരുന്നു. സുബ്ഹ് നിസ്കാരത്തിൽ അറുപത് മുതൽ നൂറ് വരെ ആയത്തുകൾ ഓതാറുണ്ടായിരുന്നു. (ബു,മു,ദ,ന,ജ)', 'أَبِي بَرْزَةَ', 'അബൂബർസ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 320, 320, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ مُحَمَّدِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا قَدِمَ الْحَجَّاجُ الْمَدِينَةَ فَسَأَلْنَا جَابِرَ بْنَ عَبْدِ اللهِ فَقَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الظُّهْرَ بِالْهَاجِرَةِ، وَالْعَصْرَ وَالشَّمْسُ نَقِيَّةٌ، وَالْمَغْرِبَ إِذَا غَرَبَتْ، وَالْعِشَاءَ أَحْيَانًا يُؤَخِّرُهَا، وَأَحْيَانًا يُعَجِّلُ، كَانَ إِذَا رَآهُمْ قَدِ اجْتَمَعُوا عَجَّلَ، وَإِذَا رَآهُمْ قَدْ أَبْطَئُوا أَخَّرَ، وَالصُّبْحَ كَانُوا - أَوْ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّيهَا بِغَلَسٍ. (م)', 'മുഹമ്മദുബ്നു അംറ്: ഹജ്ജാജ് മദീനയിലെത്തിയപ്പോൾ ഞങ്ങൾ ജാബിറുബ്നു അബ്ദുല്ലയോട് ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: നബി(സ) ഉച്ചയാവുമ്പോൾ ളുഹ്ർ നിസ്കരിക്കാറുണ്ടായിരുന്നു. സൂര്യൻ തിളക്കമുള്ളതാവുമ്പോൾ അസ്റും, അസ്തമിക്കുമ്പോൾ മഗ്‌രിബും നിസ്കരിക്കും. ഇശാ ചിലപ്പോൾ നേരത്തെയും ചിലപ്പോൾ പിന്തിച്ചും നിസ്കരിക്കും. ആളുകൾ ഒരുമിച്ചുകൂടിക്കഴിഞ്ഞാൽ ധൃതിയിൽ നിസ്ക്കരിക്കും. അവർ വരാൻ താമസിച്ചാൽ നിസ്കാരം പിന്തിപ്പിക്കും. നബി(സ) സുബ്ഹ് നിസ്കരിച്ചത് ഇരുൾ മറയുന്നതിന് മുമ്പായിരുന്നു. (മു)', 'مُحَمَّدِ بْنِ عَمْرٍو', 'മുഹമ്മദുബ്നു അംറ്', null, null, array['م']::text[], array['മു']::text[], null, null, 320, 321, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَدْرَكَ مِنَ الصَّلَاةِ رَكْعَةً فَقَدْ أَدْرَكَ الصَّلَاةَ". (ق,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിസ്കാരത്തിൽ നിന്ന് ഒരു റക്അത്ത് ഒരാൾക്ക് ലഭിച്ചാൽ അയാൾക്ക് ആ നിസ്കാരം ലഭിച്ചു." (ബു,മു,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 321, 321, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَدْرَكَ رَكْعَةً مِنَ الْجُمُعَةِ أَوْ غَيْرِهَا فَقَدْ تَمَّتْ صَلَاتُهُ". وَفِي رِوَايَةٍ: "مَنْ أَدْرَكَ رَكْعَةً مِنْ صَلَاةٍ مِنَ الصَّلَوَاتِ فَقَدْ أَدْرَكَهَا، إِلَّا أَنَّهُ يَقْضِي مَا فَاتَهُ". (ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) പറഞ്ഞു: "ജുമുഅയിൽ നിന്നോ മറ്റു നിസ്കാരങ്ങളിൽ നിന്നോ ഒരാൾക്ക് ഒരു റക്അത്ത് ലഭിച്ചാൽ അവന്റെ നിസ്കാരം പൂർണ്ണമായി."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=17 and h.hadith_no=9), 1, 'وَفِي رِوَايَةٍ: "مَنْ أَدْرَكَ رَكْعَةً مِنْ صَلَاةٍ مِنَ الصَّلَوَاتِ فَقَدْ أَدْرَكَهَا، إِلَّا أَنَّهُ يَقْضِي مَا فَاتَهُ". (ن)', 'മറ്റൊരു നിവേദനിൽ: " ഒരാൾക്ക് ഏതെങ്കിലും ഒരു നിസ്കാരത്തിൽ നിന്ന് ഒരു റക്അത്ത് ലഭിച്ചാൽ അവന് ആ നിസ്കാരം ലഭിച്ചു, എന്നാൽ അവന് നഷ്ടപ്പെട്ടത് അവൻ പൂർത്തിയാക്കണം." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَدْرَكَ رَكْعَةً مِنَ الصُّبْحِ - وَفِي رِوَايَةٍ: رَكْعَةً مِنَ الْفَجْرِ - قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ فَقَدْ أَدْرَكَهَا وَمَنْ أَدْرَكَ سَجْدَةً - وَفِي رِوَايَةٍ رَكْعَةً - مِنَ الْعَصْرِ قَبْلَ أَنْ تَغْرُبَ الشَّمْسُ فَقَدْ أَدْرَكَهَا". (م,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "സൂര്യോദയത്തിനു മുമ്പ് ഒരാൾക്ക് സുബ്ഹിൽ നിന്ന് ഒരു സുജൂദ് (റക്അത്ത്) (ഒരു റിപ്പോർട്ടിൽ: ഫജ്റിൽ നിന്നൊരു റക്അത്ത്) ലഭിച്ചാൽ അയാൾക്ക് ആ സുബ്ഹ് ലഭിച്ചു. സൂര്യാസ്തമനത്തിന് മുമ്പ് ഒരാൾക്ക് അസ്റിൽ നിന്ന് ഒരു സുജൂദ് (റക്അത്ത്) ലഭിച്ചാൽ അയാൾക്ക് ആ അസ്റ് ലഭിച്ചു." (മു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 321, 321, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=17 and h.hadith_no=10), 1, 'وَفِي رِوَايَةٍ: رَكْعَةً مِنَ الْفَجْرِ - قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ فَقَدْ أَدْرَكَهَا وَمَنْ أَدْرَكَ سَجْدَةً -', null);
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=17 and h.hadith_no=10), 2, 'وَفِي رِوَايَةٍ رَكْعَةً - مِنَ الْعَصْرِ قَبْلَ أَنْ تَغْرُبَ الشَّمْسُ فَقَدْ أَدْرَكَهَا". (م,ن,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ بُرَيْدَةَ الْأَسْلَمِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةٍ فَقَالَ: "بَكِّرُوا بِالصَّلَاةِ فِي الْيَوْمِ الْغَيْمِ، فَإِنَّهُ مَنْ فَاتَتْهُ صَلَاةُ الْعَصْرِ حَبِطَ عَمَلُهُ". (جه)', 'ബുറൈദതുൽ അസ്ലമി(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പം ഒരു യുദ്ധത്തിലായിരിക്കെ അവിടുന്ന് പറഞ്ഞു: "മേഘാവൃതമായ ദിവസം നിങ്ങൾ നേരത്തേ നിസ്കാരം നിർവ്വഹിക്കുക. കാരണം, അസ്ർ നഷ്ടപ്പെട്ടവന്റെ കർമ്മങ്ങൾ പൊളിഞ്ഞതുതന്നെ." (ജ)', 'بُرَيْدَةَ الْأَسْلَمِيِّ', 'ബുറൈദതുൽ അസ്ലമി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 321, 321, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: إِنْ كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَيُصَلِّي الصُّبْحَ، فَيَنْصَرِفُ النِّسَاءُ، فَيَمُرُّ النِّسَاءُ مُتَلَفِّفَاتٍ بِمُرُوطِهِنَّ مَا يُعْرَفْنَ مِنَ الْغَلَسِ. (ق,د,ت,ن,جه)', 'ആഇശ(റ): നബി(സ) സുബ്ഹി നിസ്കരിച്ചു കഴിഞ്ഞാൽ സ്ത്രീകൾ അവരുടെ പുതപ്പുകൊണ്ട് മൂടിക്കൊണ്ടാണ് തിരിച്ചു പോരുക. ഉദയത്തിന്റെ മുമ്പുള്ള ഇരുട്ടു കാരണം അവരെ തിരിച്ചറിയുമായിരുന്നില്ല. (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 321, 321, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ رَافِعِ بْنِ خَدِيجٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "أَسْفِرُوا بِالْفَجْرِ فَإِنَّهُ أَعْظَمُ لِلْأَجْرِ". (د,ت,ن,جه)', 'റാഫിഉബ്നു ഖദീജ്(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നിങ്ങൾ ഫജ്ർ നിസ്കാരവുമായി പ്രഭാതം പ്രകാശിതമാക്കുക. അതാണ് കൂടുതൽ പ്രതിഫലാർഹമായത്." (ദ,തു,ന,ജ)', 'رَافِعِ بْنِ خَدِيجٍ', 'റാഫിഉബ്നു ഖദീജ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 321, 322, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: {وَقُرْآنَ الْفَجْرِ إِنَّ قُرْآنَ الْفَجْرِ كَانَ مَشْهُودًا} قَالَ: "تَشْهَدُهُ مَلَائِكَةُ اللَّيْلِ وَالنَّهَارِ". (ت,جه)', 'അബൂഹുറൈറ(റ): ഫജ്ർ നിസ്കാരത്തിലെ ഖുർആൻ പാരായണം. ''നിശ്ചയം ഫജ്റിലെ ഖുർആൻ പാരായണം സാക്ഷ്യം വഹിക്കപ്പെടുന്നതാണ്.'' (അൽഇസ്റാഅ്:78) എന്ന സൂക്തത്തെക്കുറിച്ച് നബി(സ) പറഞ്ഞു: "രാത്രിയുടേയും പകലിന്റെയും മലക്കുകൾ അതിന്ന് സാക്ഷ്യം വഹിക്കുന്നതാണ്." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 322, 322, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ مُغِيثِ بْنِ سُمَيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّيْتُ مَعَ عَبْدِ اللهِ بْنِ الزُّبَيْرِ الصُّبْحَ بِغَلَسٍ، فَلَمَّا سَلَّمَ أَقْبَلْتُ عَلَى ابْنِ عُمَرَ فَقُلْتُ: مَا هَذِهِ الصَّلَاةُ؟ قَالَ: هَذِهِ صَلَاتُنَا كَانَتْ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَبِي بَكْرٍ وَعُمَرَ، فَلَمَّا طُعِنَ عُمَرُ أَسْفَرَ بِهَا عُثْمَانُ. (جه)', 'മുഗീസുബ്നു സുമയ്യ്(റ): ഞാൻ അബ്ദുല്ലാഹിബ്നു സുബൈറിനോടൊപ്പം സുബ്ഹി പ്രഭാതോദയത്തിനു മുമ്പുള്ള ഇരുട്ടുള്ളപ്പോൾ നിസ്കരിച്ചു. സലാം വീട്ടിയശേഷം ഞാൻ ഇബ്നുഉമറിന്റെ അടുത്തു ചെന്നു ചോദിച്ചു: ഇത് ഏത് നിസ്കാരമാണ്? അദ്ദേഹം പറഞ്ഞു: ഇത് ഞങ്ങൾ റസൂലി(സ)ന്റെയും അബൂബക്കറിന്റെയും ഉമറിന്റെയും കൂടെ നിസ്കരിച്ച നിസ്കാരമാണ്. ഉമർ(റ) വധിക്കപ്പെട്ടശേഷം ഉസ്മാൻ(റ) അതു പ്രഭാത സമയത്താക്കി.² (ജ)', 'مُغِيثِ بْنِ سُمَيٍّ', 'മുഗീസുബ്നു സുമയ്യ്(റ)', '². സുബ്ഹി നിസ്കാരത്തിന്റെ സമയത്ത് ഇരുളിൽ മറഞ്ഞ് നിന്നാണ് ഘാതകൻ ഉമർ(റ)വിനെ കുത്തിയത്. ഇത്തരത്തിലുള്ള ഭീകരാക്രമണങ്ങൾ സംഭവിക്കാതിരിക്കാനാണ് ഉസ്മാൻ(റ) സുബ്ഹ് നിസ്കാരത്തെ നേരം പുലരുവോളം പിന്തിച്ചത് എന്നുകാണാം.', null, array['جه']::text[], array['ജ']::text[], null, null, 322, 322, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ زَيْدَ بْنَ ثَابِتٍ قَالَ: تَسَحَّرْنَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ قُمْنَا إِلَى الصَّلَاةِ، قُلْتُ: كَمْ كَانَ بَيْنَهُمَا؟ قَالَ: قَدْرُ خَمْسِينَ أَوْ سِتِّينَ يَعْنِي آيَةً. (خ)', 'അനസ്(റ): സൈദ്ബ്നു സാബിത്(റ) പറഞ്ഞു: ഞങ്ങൾ നബി(സ)യോടൊപ്പം അത്താഴം കഴിക്കുകയും പിന്നെ നിസ്കാരത്തിനു നിൽക്കുകയും ചെയ്തു. ഞാൻ ചോദിച്ചു: അവക്കിടയിൽ എത്ര സമയമുണ്ടായിരുന്നു?. അദ്ദേഹം പറഞ്ഞു: ഏതാണ്ട് അമ്പതോ അറുപതോ ആയത്ത് (പാരായണം ചെയ്യുന്നത്ര). (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 322, 322, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ أَتَسَحَّرُ فِي أَهْلِي، ثُمَّ يَكُونُ سُرْعَةٌ بِي أَنْ أُدْرِكَ صَلَاةَ الْفَجْرِ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (خ)', 'സഹ്ലുബ്നു സഅദ്(റ): ഞാൻ എന്റെ കുടുംബത്തോടൊപ്പം അത്താഴം കഴിക്കാറുണ്ടായിരുന്നു. പിന്നെ നബി(സ)യോടൊപ്പം ഫജ്ർ നിസ്കാരത്തിൽ പങ്കെടുക്കാൻ എനിക്ക് ധൃതിയിൽ പോകേണ്ടിവരാറുണ്ട്. (ബു)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്ലുബ്നു സഅദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 322, 322, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ صَلَّى الْبَرْدَيْنِ دَخَلَ الْجَنَّةَ". (ق)', 'അബൂമൂസ(റ): നബി(സ) പറഞ്ഞു: "രണ്ട് തണുപ്പ് സമയത്തെ നിസ്കാരങ്ങൾ (ഫജ്റും അസ്റും) ആർ നിർവ്വഹിക്കുന്നുവോ അവൻ സ്വർഗ്ഗത്തിൽ പ്രവേശിച്ചു." (ബു,മു)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 322, 322, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ أَبِي بَرْزَةَ الْأَسْلَمِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي صَلَاةَ الْهَجِيرِ الَّتِي تَدْعُونَهَا الظُّهْرَ إِذَا دَحَضَتِ الشَّمْسُ. (ق,د,ن,جه)', 'അബൂബർസതുൽ അസ്ലമി(റ): നിങ്ങൾ ളുഹ്ർ എന്നു വിളിക്കുന്ന ഹജീർ നിസ്കാരം നബി(സ) നിസ്കരിച്ചിരുന്നത് സൂര്യൻ ആകാശമദ്ധ്യേ നിന്ന് അൽപം മാറുമ്പോഴായിരുന്നു. (ബു,മു,ദ,ന,ജ)', 'أَبِي بَرْزَةَ الْأَسْلَمِيِّ', 'അബൂബർസതുൽ അസ്ലമി(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 323, 323, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ خَبَّابٍ رَضِيَ اللهُ عَنْهُ قَالَ: شَكَوْنَا إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَرَّ الرَّمْضَاءِ، فَلَمْ يُشْكِنَا. (م,ن,جه)', 'ഖബ്ബാബ്(റ): ഞങ്ങൾ മണലിന്റെ ചൂടിനെക്കുറിച്ചു നബി(സ)യോട് പരാതിപ്പെട്ടിരുന്നു. എന്നാൽ നബി(സ) ഒരിക്കലും ഞങ്ങളോട് പരാതിപ്പെട്ടിരുന്നില്ല. (മു,ന,ജ)', 'خَبَّابٍ', 'ഖബ്ബാബ്(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 323, 323, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا رَأَيْتُ أَحَدًا كَانَ أَشَدَّ تَعْجِيلًا لِلظُّهْرِ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَلَا مِنْ أَبِي بَكْرٍ وَلَا مِنْ عُمَرَ. (ت)', 'ആഇശ(റ): അല്ലാഹുവിന്റെ ദൂതനേക്കാൾ ളുഹ്ർ നിസ്കരിക്കാൻ ധൃതി കാണിക്കുന്ന മറ്റൊരാളെ ഞാൻ കണ്ടിട്ടില്ല. അപ്രകാരം തന്നെയായിരുന്നു അബൂബക്കറും ഉമറും(റ). (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 323, 323, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى الظُّهْرَ حِينَ زَالَتِ الشَّمْسُ. (خ,ت,ن)', 'അനസുബ്നു മാലിക്(റ): സൂര്യൻ മദ്ധ്യത്തിൽ നിന്നും തെറ്റിയപ്പോൾ നബി(സ) ളുഹ്ർ നിസ്കരിച്ചു. (ബു,തു,ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ','ت','ن']::text[], array['ബു','തു','ന']::text[], null, null, 323, 323, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا نَزَلَ مَنْزِلًا، لَمْ يَرْتَحِلْ مِنْهُ حَتَّى يُصَلِّيَ الظُّهْرَ. فَقَالَ رَجُلٌ: وَإِنْ كَانَتْ بِنِصْفِ النَّهَارِ؟ قَالَ: وَإِنْ كَانَتْ بِنِصْفِ النَّهَارِ (ن)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) യാത്രയിൽ ഒരിടത്തിറങ്ങിയാൽ അവിടെവെച്ച് ളുഹ്ർ നിസ്കരിക്കാതെ യാത്ര പുനരാരംഭിക്കാറില്ല. ഒരാൾ ചോദിച്ചു: ഉച്ച സമയത്താണെങ്കിലോ? അനസ്(റ) പറഞ്ഞു: അതെ! ഉച്ച സമയത്തായാലും ശരി. (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 323, 323, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "إِذَا اشْتَدَّ الْحَرُّ فَأَبْرِدُوا عَنِ الصَّلَاةِ، فَإِنَّ شِدَّةَ الْحَرِّ مِنْ فَيْحِ جَهَنَّمَ". (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ചൂട് കഠിനമായാൽ അൽപം ശാന്തത വന്ന ശേഷം നിസ്കരിക്കുക. കാരണം, കഠിന ചൂട് നരകത്തിന്റെ ആവിയാണ്. (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 323, 323, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ فِي سَفَرٍ وَمَعَهُ بِلَالٌ، فَأَرَادَ أَنْ يُقِيمَ، فَقَالَ: "أَبْرِدْ" ثُمَّ أَرَادَ أَنْ يُقِيمَ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَبْرِدْ فِي الظُّهْرِ" قَالَ: حَتَّى رَأَيْنَا فَيْءَ التُّلُولِ، ثُمَّ أَقَامَ فَصَلَّى، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ شِدَّةَ الْحَرِّ مِنْ فَيْحِ جَهَنَّمَ، فَأَبْرِدُوا عَنِ الصَّلَاةِ". (ق,د,ت)', 'അബൂദർറ്(റ): നബി(സ) യാത്രയിലായിരുന്നു. കൂടെ ബിലാലുമുണ്ട്. ബിലാൽ ഇഖാമത്തിന് ഉദ്ദേശിച്ചു. നബി(സ) പറഞ്ഞു: "അൽപം ആശ്വാസം വരുത്തുക." അൽപം കഴിഞ്ഞ് ഇഖാമത്തിനുദ്ദേശിച്ചപ്പോൾ പറഞ്ഞു: "ചൂടിൽനിന്ന് ആശ്വാസം വരുത്തിയ ശേഷം ളുഹ്ർ നിസ്കരിക്കുക." അബൂദർറ് പറഞ്ഞു: അങ്ങനെ ഞങ്ങൾ തണലിന്റെ അടയാളം കണ്ടു. ശേഷം ഇഖാമത്ത് വിളിച്ച് നിസ്കരിച്ചു. നബി(സ) പറഞ്ഞു: "നിശ്ചയം, കഠിന ചൂട് നരകത്തിൽ നിന്നുള്ള ആവിയാണ്. അതിനാൽ ചൂടിന് അൽപം ആശ്വാസം വന്നശേഷം നിസ്കരിക്കുക." (ബു,മു,ദ,തു)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 323, 324, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ قَدْرُ صَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الظُّهْرَ فِي الصَّيْفِ ثَلَاثَةَ أَقْدَامٍ إِلَى خَمْسَةِ أَقْدَامٍ وَفِي الشِّتَاءِ خَمْسَةَ أَقْدَامٍ إِلَى سَبْعَةِ أَقْدَامٍ. (د,ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ)യുടെ ളുഹ്ർ നിസ്കാര സമയം ചൂടുകാലത്ത് മൂന്ന് മുതൽ അഞ്ച് കാലടി വരെയും തണുപ്പ് കാലത്ത് അഞ്ച് മുതൽ ഏഴ് കാലടി³ വരെയുമായിരുന്നു.⁴ (ദ,ന)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', '³. നിഴൽ അളന്ന് സമയം കണക്കാക്കുന്ന ഒരു രീതി.
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا كَانَ الْحَرُّ أَبْرَدَ بِالصَّلَاةِ، وَإِذَا كَانَ الْبَرْدُ عَجَّلَ. (ن)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) ചൂടുള്ളപ്പോൾ നിസ്കാരത്തെ പിന്തിപ്പിക്കുകയും തണുപ്പുള്ളപ്പോൾ അത് നിർവ്വഹിക്കുവാൻ ധൃതി കാണിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 324, 324, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى بِالْمَدِينَةِ سَبْعًا وَثَمَانِيًا الظُّهْرَ وَالْعَصْرَ، وَالْمَغْرِبَ وَالْعِشَاءَ، فَقَالَ أَيُّوبُ لَعَلَّهُ فِي لَيْلَةٍ مَطِيرَةٍ. (ق)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) മദീനയിൽ വെച്ച് ഏഴും (മഗ്രിബ്, ഇശാ) എട്ടും (ളുഹ്ർ, അസ്ർ) നിസ്കരിച്ചു. അയ്യൂബ് പറയുന്നു അതു ചിലപ്പോൾ മഴ പെയ്ത രാത്രിയാവാം. (ബു,മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 324, 324, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ أَبِي جُحَيْفَةَ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِالْهَاجِرَةِ إِلَى الْبَطْحَاءِ فَتَوَضَّأَ، وَصَلَّى الظُّهْرَ رَكْعَتَيْنِ وَالْعَصْرَ رَكْعَتَيْنِ وَبَيْنَ يَدَيْهِ عَنَزَةٌ. (ن)', 'അബൂജുഹൈഫ(റ): നബി(സ) ഉച്ചസമയത്ത് ബത്ഹാഇലേക്ക് പുറപ്പെട്ടു. അവിടെ വെച്ച് വുദു ചെയ്ത് ളുഹ്ർ രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. അസ്ർ രണ്ട് റകഅത്ത് നിർവ്വഹിച്ചു. അവിടുത്തെ മുന്നിൽ ഒരു വടി ഉണ്ടായിരുന്നു. (ന)', 'أَبِي جُحَيْفَةَ', 'അബൂജുഹൈഫ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 324, 324, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّيْتُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الظُّهْرَ بِالْمَدِينَةِ أَرْبَعًا، وَبِذِي الْحُلَيْفَةِ الْعَصْرَ رَكْعَتَيْنِ. (ن)', 'അനസ്(റ): ഞാൻ നബി(സ)യോടൊപ്പം മദീനയിൽവെച്ചു ളുഹ്ർ നാല് റക്അത്ത് നിർവ്വഹിച്ചു. ദുൽഹുലൈഫയിൽ വെച്ച് അസ്ർ രണ്ട് റക്അത്താണ് നിസ്കരിച്ചത്. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 324, 324, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي الْعَصْرَ وَالشَّمْسُ بَيْضَاءُ مُرْتَفِعَةٌ حَيَّةٌ، فَيَذْهَبُ الذَّاهِبُ إِلَى الْعَوَالِي وَالشَّمْسُ مُرْتَفِعَةٌ. (ق,د,ن,جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) അസ്ർ നിസ്കരിക്കുന്നത് സൂര്യൻ സജീവമായി ഉയർന്നുനിന്ന് വെളുത്ത പ്രകാശം പൊഴിച്ചു കൊണ്ടിരിക്കുമ്പോഴായിരുന്നു. സൂര്യൻ ഉയർന്നു നിൽക്കെ (നിസ്കാരശേഷം) ആവശ്യക്കാർക്ക് ഗ്രാമങ്ങളിൽ പോയി തിരിച്ചുവരാനും കഴിഞ്ഞിരുന്നു. (ബു,മു,ദ,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 324, 324, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي الْعَصْرَ وَالشَّمْسُ فِي حُجْرَتِهَا قَبْلَ أَنْ تَظْهَرَ. (ق,ت,ن,جه)', 'ആഇശ(റ): സൂര്യപ്രകാശത്തിന്റെ വെയിൽ അവരുടെ മുറിക്കകത്ത് ജ്വലിച്ചു കൊണ്ടിരിക്കുമ്പോഴായിരുന്നു നബി(സ) അസ്ർ നിസ്കരിച്ചിരുന്നത്. (ബു,മു,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 324, 325, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ عَلِيِّ بْنِ شَيْبَانَ رَضِيَ اللهُ عَنْهُ قَالَ: قَدِمْنَا عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ، فَكَانَ يُؤَخِّرُ الْعَصْرَ مَا دَامَتِ الشَّمْسُ بَيْضَاءَ نَقِيَّةً (د)', 'അലിയ്യുബ്നു ശൈബാൻ(റ): ഞങ്ങൾ മദീനയിൽ നബി(സ)യുടെ അടുത്തു ചെന്നു. അപ്പോൾ സൂര്യൻ വെള്ള നിറത്തിൽ ആയിരിക്കുന്നേടത്തോളം സമയം അസ്റിനെ പിന്തിച്ചിരുന്നു. (ദ)', 'عَلِيِّ بْنِ شَيْبَانَ', 'അലിയ്യുബ്നു ശൈബാൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 325, 325, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ يَوْمَ الْخَنْدَقِ: حَبَسُونَا عَنْ صَلَاةِ الْوُسْطَى صَلَاةِ الْعَصْرِ، مَلَأَ اللهُ بُيُوتَهُمْ وَقُبُورَهُمْ نَارًا". (ق,د,ت,ن,جه)', 'അലി(റ): റസൂൽ(സ) ഖൻദഖ് ദിവസം പറഞ്ഞു: "അവർ (ശത്രുക്കൾ) നമ്മെ മധ്യാഹ്ന നിസ്കാരം (അസ്ർ) നിർവ്വഹിക്കുന്നതിൽ നിന്നും തടഞ്ഞു. അല്ലാഹു അവരുടെ ഭവനങ്ങളും ഖബറിടങ്ങളും തീ കൊണ്ടു നിറക്കട്ടെ." (ബു,മു,ദ,തു,ന,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 325, 325, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ أَبِي يُونُسَ مَوْلَى عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّهُ قَالَ: أَمَرَتْنِي عَائِشَةُ أَنْ أَكْتُبَ لَهَا مُصْحَفًا، وَقَالَتْ: إِذَا بَلَغْتَ هَذِهِ الْآيَةَ فَآذِنِّي: {حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلَاةِ الْوُسْطَى} فَلَمَّا بَلَغْتُهَا آذَنْتُهَا، فَأَمْلَتْ عَلَيَّ: {حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلَاةِ الْوُسْطَى -وَصَلَاةِ الْعَصْرِ- وَقُومُوا لِلَّهِ قَانِتِينَ} ثُمَّ قَالَتْ عَائِشَةُ: سَمِعْتُهَا مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (م,د,ت,ن)', 'ആഇശ(റ)യുടെ ഭൃത്യനായ അബൂയൂനുസ്(റ): ആഇശ(റ) അവർക്കായി ഒരു മുസ്ഹഫ് എഴുതാൻ എന്നോട് ആവശ്യപ്പെട്ടു. എന്നിട്ടു പറഞ്ഞു: "നിങ്ങൾ നിസ്കാരങ്ങൾ നിലനിർത്തുക, മദ്ധ്യനിസ്കാരവും" എന്ന ആയത്ത് എത്തിയാൽ എന്നെ വിളിക്കണം. അതെത്തിയപ്പോൾ ഞാനവരെ വിളിച്ചു. അവർ എനിക്ക് ഓതിക്കേൾപ്പിച്ചു "നിങ്ങൾ നിസ്കാരങ്ങൾ നിലനിർത്തുക മധ്യനിസ്കാരവും (അഥവാ അസ്ർ നിസ്കാരം) നിങ്ങൾ അല്ലാഹുവിന് ഭയഭക്തിയോടെ കീഴ്പ്പെട്ട് നിസ്കരിക്കുക." ആഇശ(റ) പറഞ്ഞു: ഞാനത് അല്ലാഹുവിന്റെ ദൂതനിൽ നിന്നും കേട്ടതാണ്. (മു,ദ,തു,ന)', 'أَبِي يُونُسَ مَوْلَى عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 325, 325, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ زَيْدِ بْنِ ثَابِتٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الظُّهْرَ بِالْهَاجِرَةِ، وَلَمْ يَكُنْ يُصَلِّي صَلَاةً أَشَدَّ عَلَى أَصْحَابِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْهَا، فَنَزَلَتْ: {حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلَاةِ الْوُسْطَى} وَقَالَ: "إِنَّ قَبْلَهَا صَلَاتَيْنِ وَبَعْدَهَا صَلَاتَيْنِ". (د)', 'സൈദുബ്നു സാബിത്(റ): നബി(സ) ളുഹ്ർ നിസ്കരിച്ചിരുന്നത് ഉച്ചസമയത്തായിരുന്നു. റസൂലിന്റെ സഹാബികൾക്ക് വിഷമകരമായ മറ്റൊരു നിസ്കാരവും നബിസ) നിസ്കരിച്ചിട്ടില്ല. അപ്പോഴാണ് "നിങ്ങൾ നിസ്കാരങ്ങളെ കാത്തുസൂക്ഷിക്കുക പ്രത്യേകിച്ചും മദ്ധ്യനിസ്കാരം" എന്ന സൂക്തം അവതരിച്ചത്. നബി(സ) പറഞ്ഞു: "അതിനുമുമ്പ് രണ്ടു നിസ്കാരമുണ്ട്. അതിനു ശേഷവും രണ്ട് നിസ്കാരമുണ്ട്." (ദ)', 'زَيْدِ بْنِ ثَابِتٍ', 'സൈദുബ്നു സാബിത്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 325, 325, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنِ الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلْنَا عَلَى أَنَسِ بْنِ مَالِكٍ بَعْدَ الظُّهْرِ، فَقَامَ يُصَلِّي الْعَصْرَ، فَلَمَّا فَرَغَ مِنْ صَلَاتِهِ ذَكَرْنَا تَعْجِيلَ الصَّلَاةِ - أَوْ ذَكَرَهَا - فَقَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "تِلْكَ صَلَاةُ الْمُنَافِقِينَ، تِلْكَ صَلَاةُ الْمُنَافِقِينَ، تِلْكَ صَلَاةُ الْمُنَافِقِينَ، يَجْلِسُ أَحَدُهُمْ حَتَّى إِذَا اصْفَرَّتِ الشَّمْسُ فَكَانَتْ بَيْنَ قَرْنَيْ شَيْطَانٍ - أَوْ عَلَى قَرْنَيِ الشَّيْطَانِ - قَامَ فَنَقَرَ أَرْبَعًا، لَا يَذْكُرُ اللهَ فِيهَا إِلَّا قَلِيلًا". (م,د,ت,ن)', 'അലാഉബ്നു അബ്ദുർറഹ്മാൻ: ളുഹ്റിനുശേഷം ഞങ്ങൾ അനസുബ്നു മാലിക്(റ)ന്റെ അടുത്തു ചെന്നു. അപ്പോൾ അദ്ദേഹം അസ്ർ നിസ്കരിക്കുകയായിരുന്നു. അദ്ദേഹം നിസ്കാരത്തിൽനിന്നു വിരമിച്ചപ്പോൾ നിസ്കാരത്തിൽ ധൃതി കാണിക്കുന്നത് സംബന്ധിച്ച് ഞങ്ങളോ അദ്ദേഹമോ സംസാരിച്ചു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്. "അത് കപട വിശ്വാസികളുടെ നിസ്കാരമാണ്, അത് കപട വിശ്വാസികളുടെ നിസ്കാരമാണ്: സൂര്യൻ മഞ്ഞ വർണ്ണമാകുകയും അങ്ങിനെ അതു പിശാചിന്റെ രണ്ട് കൊമ്പുകൾക്കിടയിലാവുകയും ചെയ്യുന്നതുവരെ ഒരാൾ കാത്തിരിക്കുകയും എന്നിട്ട് എഴുന്നേറ്റു നാലു പ്രാവശ്യം കൊത്തിപ്പെറുക്കുകയും ചെയ്യുന്നത്. അതിലാണെങ്കിൽ അല്ലാഹുവിനെ വളരെ കുറച്ചേ സ്മരിക്കുന്നുള്ളൂ." (മു,ദ,തു,ന)', 'الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ', 'അലാഉബ്നു അബ്ദുർറഹ്മാൻ', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 325, 326, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ عَبْدِاللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الَّذِي تَفُوتُهُ صَلَاةُ الْعَصْرِ فَكَأَنَّمَا وُتِرَ أَهْلَهُ وَمَالَهُ" (ق,ت,ن,جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "അസ്ർ നിസ്കാരം നഷ്ടപ്പെടുത്തിയവൻ ധനത്തേയും കുടുംബത്തേയും ഒറ്റപ്പെടുത്തിയവനെപ്പോലെയാണ്." (ബു,മു,തു,ന,ജ)', 'عَبْدِاللهِ بْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 326, 326, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنَّا نُصَلِّي الْعَصْرَ، ثُمَّ يَخْرُجُ الْإِنْسَانُ إِلَى بَنِي عَمْرِو بْنِ عَوْفٍ فَيَجِدُهُمْ يُصَلُّونَ الْعَصْرَ. (خ)', 'അനസ്(റ): ഞങ്ങൾ അസ്ർ നിസ്കരിക്കും. തുടർന്ന് ഞങ്ങളിൽ ചിലർ അംറുബ്നു ഔഫ് ഗോത്രക്കാരുടെ അടുത്തു ചെന്നാൽ അവർ അസ്ർ നിസ്കരിക്കുന്നത് കാണാമായിരുന്നു. (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 326, 326, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ عَبْدِاللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا أَنَّهُ سَمِعَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّمَا بَقَاؤُكُمْ فِيمَا سَلَفَ قَبْلَكُمْ مِنَ الْأُمَمِ كَمَا بَيْنَ صَلَاةِ الْعَصْرِ إِلَى غُرُوبِ الشَّمْسِ، أُوتِيَ أَهْلُ التَّوْرَاةِ التَّوْرَاةَ، فَعَمِلُوا حَتَّى إِذَا انْتَصَفَ النَّهَارُ عَجَزُوا، فَأُعْطُوا قِيرَاطًا قِيرَاطًا، ثُمَّ أُوتِيَ أَهْلُ الْإِنْجِيلِ الْإِنْجِيلَ، فَعَمِلُوا إِلَى صَلَاةِ الْعَصْرِ، ثُمَّ عَجَزُوا، فَأُعْطُوا قِيرَاطًا قِيرَاطًا، ثُمَّ أُوتِينَا الْقُرْآنَ، فَعَمِلْنَا إِلَى غُرُوبِ الشَّمْسِ، فَأُعْطِينَا قِيرَاطَيْنِ قِيرَاطَيْنِ". فَقَالَ أَهْلُ الْكِتَابَيْنِ: أَيْ رَبَّنَا! أَعْطَيْتَ هَؤُلَاءِ قِيرَاطَيْنِ قِيرَاطَيْنِ، وَأَعْطَيْتَنَا قِيرَاطًا قِيرَاطًا، وَنَحْنُ كُنَّا أَكْثَرَ عَمَلًا، قَالَ: قَالَ اللهُ عَزَّ وَجَلَّ: هَلْ ظَلَمْتُكُمْ مِنْ أَجْرِكُمْ مِنْ شَيْءٍ، قَالُوا: لَا، قَالَ: فَهُوَ فَضْلِي أُوتِيهِ مَنْ أَشَاءُ". (خ)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) പറയുന്നതായി അദ്ദേഹം കേട്ടു: "മുൻകഴിഞ്ഞ സമൂഹങ്ങളെ അപേക്ഷിച്ച് നിങ്ങളുടെ നിലനിൽപ് അസ്ർ നിസ്കാരം മുതൽ സൂര്യാസ്തമയം വരെയുള്ള സമയമാണ്. തൗറാത്തിന്റെ ആളുകൾക്ക് തൗറാത്ത് നൽകപ്പെട്ടു. മധ്യാഹ്നംവരെ അവർ കർമ്മങ്ങൾ ചെയ്തു. തുടർന്ന് യഥാവിധി കർമ്മം ചെയ്യുന്നതിൽ അവർ പരാജയപ്പെട്ടപ്പോൾ അവർക്ക് ഓരോ കൂമ്പാരം നൽകപ്പെട്ടു. പിന്നെ ഇഞ്ചീലിന്റെ ആളുകൾക്ക് ഇഞ്ചീൽ നൽകപ്പെട്ടു. അവർ അസ്ർ വരെ കർമ്മങ്ങൾ ചെയ്തു. അവരും അശക്തരായപ്പോൾ അവർക്കും ഓരോ കൂമ്പാരം നൽകി. പിന്നെ നമുക്ക് ഖുർആൻ നൽകപ്പെട്ടു. സൂര്യാസ്തമയംവരെ നാം കർമ്മങ്ങൾ ചെയ്തു. നമുക്ക് ഈരണ്ടീരണ്ട് കൂമ്പാരങ്ങൾ നൽകപ്പെട്ടു. അപ്പോൾ വേദക്കാർ ചോദിക്കും: ഞങ്ങളുടെ നാഥാ! നീ ഇവർക്ക് ഈരണ്ട് കൂമ്പാരങ്ങൾ നൽകി. ഞങ്ങൾക്കാണെങ്കിൽ ഓരോ കൂമ്പാരമേ നൽകിയതുള്ളൂ. എന്നാൽ ഞങ്ങളാകട്ടെ അധികകാലം കർമ്മങ്ങൾ ചെയ്തവരുമാണ്. അല്ലാഹു ചോദിക്കും: നാം നിങ്ങളോട് പ്രതിഫലത്തിൽ വല്ല അതിക്രമവും കാണിച്ചിട്ടുണ്ടോ? അവർ പറയും: ഇല്ല. അപ്പോൾ അല്ലാഹു പറയും: അതെന്റെ കാരുണ്യമാണ് ഞാനുദ്ദേശിക്കുന്നവർക്കത് നൽകുന്നു." (ബു)', 'عَبْدِاللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 326, 326, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ أَبِي بَصْرَةَ الْغِفَارِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّى بِنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْعَصْرَ بِالْمُخَمَّصِ قَالَ: "إِنَّ هَذِهِ الصَّلَاةَ عُرِضَتْ عَلَى مَنْ كَانَ قَبْلَكُمْ فَضَيَّعُوهَا، وَمَنْ حَافَظَ عَلَيْهَا كَانَ لَهُ أَجْرُهُ مَرَّتَيْنِ، وَلَا صَلَاةَ بَعْدَهَا حَتَّى يَطْلُعَ الشَّاهِدُ". - وَالشَّاهِدُ النَّجْمُ. (م)', 'അബൂബസറതുൽ ഗിഫാരി(റ): മഖ്മിസിൽ വെച്ച് നബി(സ) ഞങ്ങളെയുമായി അസ്ർ നിസ്കരിച്ചു. എന്നിട്ട് പറഞ്ഞു: "ഈ നിസ്കാരം നിങ്ങൾക്കു മുമ്പുള്ള സമൂഹങ്ങളോട് കൽപിക്കപ്പെടുകയും അവരതിനെ പാഴാക്കുകയും ചെയ്തു. ആർ അതിനെ നിലനിർത്തുന്നുവോ അയാൾക്ക് രണ്ട് പ്രാവശ്യം പ്രതിഫലം ലഭിക്കുന്നതാണ്. അതിനുശേഷം ശാഹിദ് ഉദിക്കുംവരെ നിസ്കാരമില്ല."-ശാഹിദ് ഒരു നക്ഷത്രമാണ്.- (മു)', 'أَبِي بَصْرَةَ الْغِفَارِيِّ', 'അബൂബസറതുൽ ഗിഫാരി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 326, 326, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ عُمَارَةَ بْنِ رُوَيْبَةَ الثَّقَفِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَنْ يَلِجَ النَّارَ مَنْ صَلَّى قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا". (ن)', 'ഉമാറതുബ്നു റുവൈബ(റ): നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "സൂര്യോദയത്തിന്നു മുമ്പും സൂര്യാസ്തമയത്തിന്ന് മുമ്പും നിസ്കരിക്കുന്നവൻ നരകത്തിൽ പ്രവേശിക്കുകയില്ല." (ന)', 'عُمَارَةَ بْنِ رُوَيْبَةَ الثَّقَفِيِّ', 'ഉമാറതുബ്നു റുവൈബ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 327, 327, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "شَغَلُونَا عَنِ الصَّلَاةِ الْوُسْطَى حَتَّى غَرَبَتِ الشَّمْسُ". (ن)', 'അലി(റ): നബി(സ) പറഞ്ഞു: "മദ്ധ്യനിസ്കാരം നിർവ്വഹിക്കുന്നതിൽനിന്ന് സൂര്യാസ്തമയം വരെ നമ്മളെ അവർ (ശത്രുക്കൾ) തടഞ്ഞു." (ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 327, 327, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا أَنَّهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَشَدَّ تَعْجِيلًا لِلظُّهْرِ مِنْكُمْ، وَأَنْتُمْ أَشَدُّ تَعْجِيلًا لِلْعَصْرِ مِنْهُ. (ت)', 'ഉമ്മുസലമ(റ): നബി(സ) ളുഹ്ർ നിസ്കരിക്കാൻ നിങ്ങളേക്കാൾ ധൃതി കാണിച്ചിരുന്നു. നിങ്ങളാകട്ടെ അസ്ർ നിസ്കാരത്തിന്ന് നബിയേക്കാൾ ധൃതി കാണിക്കുന്നു. (തു)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 327, 327, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلَ رَجُلٌ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ مَوَاقِيتِ الصَّلَاةِ فَقَالَ: "صَلِّ مَعِي". فَصَلَّى الظُّهْرَ حِينَ زَاغَتِ الشَّمْسُ، وَالْعَصْرَ حِينَ كَانَ فَيْءُ كُلِّ شَيْءٍ مِثْلَهُ، وَالْمَغْرِبَ حِينَ غَرُبَتِ الشَّمْسُ، وَالْعِشَاءَ حِينَ غَابَ الشَّفَقُ، قَالَ: ثُمَّ صَلَّى الظُّهْرَ حِينَ كَانَ فَيْءُ الْإِنْسَانِ مِثْلَهُ، وَالْعَصْرَ حِينَ كَانَ فَيْءُ الْإِنْسَانِ مِثْلَيْهِ، وَالْمَغْرِبَ حِينَ كَانَ قُبَيْلَ غَيْبُوبَةِ الشَّفَقِ، ثُمَّ قَالَ فِي الْعِشَاءِ: أُرَى إِلَى ثُلُثِ اللَّيْلِ. (ن)', 'ജാബിർ(റ): ഒരാൾ നബി(സ)യോട് നിസ്കാര സമയത്തെക്കുറിച്ച് ചോദിച്ചപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ എന്റെ കൂടെ നിസ്കരിക്കുക." അങ്ങനെ സൂര്യൻ ആകാശ മദ്ധ്യത്തിൽനിന്ന് ചാഞ്ഞപ്പോൾ ളുഹ്ർ നിസ്കരിച്ചു. അസ്ർ ഓരോ വസ്തുവിന്റെയും നിഴൽ അതിന്റെ വലുപ്പത്തിലായപ്പോൾ നിർവ്വഹിച്ചു. സൂര്യൻ അസ്തമിച്ചപ്പോൾ മഗ്രിബ് നിർവ്വഹിച്ചു. ആകാശത്തിലെ ചുകപ്പ് നിറം മാഞ്ഞപ്പോൾ ഇശാ നിസ്കരിച്ചു. തുടർന്ന് അയാൾ പറഞ്ഞു: പിന്നെ ഒരാളുടെ നിഴൽ അത്രയും ആയപ്പോൾ നബി(സ) ളുഹ്ർ നിസ്കരിച്ചു. മനുഷ്യന്റെ നിഴൽ അവന്റെ ഇരട്ടിയായപ്പോൾ അസ്ർ നിസ്കരിച്ചു. അസ്തമനശോഭ മായുന്നതിന്റെ തൊട്ടുമുമ്പ് മഗ്രിബും. ഇശാഇനെ സംബന്ധിച്ച് അദ്ദേഹം പറഞ്ഞു: രാത്രിയുടെ മൂന്നിൽ ഒന്നായപ്പോഴാന്ന് ഇശാ നിസ്കരിച്ചത് എന്ന് തോന്നുന്നു. (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 327, 327, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي بِنَا الْعَصْرَ وَالشَّمْسُ بَيْضَاءُ مُحَلِّقَةٌ (ن)', 'അനസുബ്നുമാലിക്(റ): സൂര്യൻ വെളുത്ത വളയമായി കാണുന്ന സമയത്തായിരുന്നു നബി(സ) ഞങ്ങളെയുമായി അസ്ർ നിസ്കരിച്ചിരുന്നത്. (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 327, 327, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ أَبِي أُمَامَةَ بْنِ سَهْلٍ رَضِيَ اللهُ عَنْهُ يَقُولُ: صَلَّيْنَا مَعَ عُمَرَ بْنِ عَبْدِ الْعَزِيزِ الظُّهْرَ، ثُمَّ خَرَجْنَا حَتَّى دَخَلْنَا عَلَى أَنَسِ بْنِ مَالِكٍ فَوَجَدْنَاهُ يُصَلِّي الْعَصْرَ، قُلْتُ: يَا عَمِّ! مَا هَذِهِ الصَّلَاةُ الَّتِي صَلَّيْتَ؟ قَالَ: الْعَصْرَ، وَهَذِهِ صَلَاةُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الَّتِي كُنَّا نُصَلِّي. (ن)', 'അബൂഉമാമതുബ്നു സഹ്ൽ(റ): ഞങ്ങൾ ഉമറുബ്നു അബ്ദിൽ അസീസി(റ)നോടൊപ്പം ളുഹ്ർ നിസ്കരിച്ചു. തുടർന്ന് അനസ്(റ)ന്റെ അടുത്തെത്തി. അപ്പോൾ അദ്ദേഹം അസ്ർ നിസ്കരിക്കുന്നത് ഞങ്ങൾ കണ്ടു. ഞാൻ ചോദിച്ചു; പിതൃവ്യാ! താങ്കളേതാണ് നിസ്കരിച്ചത്? അദ്ദേഹം പറഞ്ഞു: അസ്ർ, ഞങ്ങൾ നബി(സ)യോടൊപ്പം ഇപ്രകാരം നിസ്കരിച്ചതാണ്. (ന)', 'أَبِي أُمَامَةَ بْنِ سَهْلٍ', 'അബൂഉമാമതുബ്നു സഹ്ൽ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 327, 327, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي الْعَصْرَ، ثُمَّ يَذْهَبُ الذَّاهِبُ إِلَى قُبَاءَ فَيَأْتِيهِمْ وَهُمْ يُصَلُّونَ. وَفِي رِوَايَةٍ: وَالشَّمْسُ مُرْتَفِعَةٌ. (ن)', 'അനസ്(റ): നബി(സ) അസ്ർ നിസ്കരിക്കുകയും പിന്നെ ഖുബായിലേക്ക് പോകുന്നവൻ അവിടെയെത്തുമ്പോൾ അവർ നിസ്കരിക്കുകയായും ചെയ്യുമായിരുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: സൂര്യൻ ഉയരത്തിൽ തന്നെയായിരിക്കെ എന്നുകൂടിയുണ്ട്. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 328, 328, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=17 and h.hadith_no=48), 1, 'وَفِي رِوَايَةٍ: وَالشَّمْسُ مُرْتَفِعَةٌ. (ن)', 'മറ്റൊരു നിവേദനിൽ: സൂര്യൻ ഉയരത്തിൽ തന്നെയായിരിക്കെ എന്നുകൂടിയുണ്ട്. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ: أَنَّ عُمَرَ بْنَ الْخَطَّابِ يَوْمَ الْخَنْدَقِ جَعَلَ يَسُبُّ كُفَّارَ قُرَيْشٍ وَقَالَ: يَا رَسُولَ اللهِ! وَاللهِ! مَا كِدْتُ أَنْ أُصَلِّيَ الْعَصْرَ حَتَّى كَادَتْ أَنْ تَغْرُبَ الشَّمْسُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "فَوَاللهِ! إِنْ صَلَّيْتُهَا". فَنَزَلْنَا إِلَى بُطْحَانَ، فَتَوَضَّأَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَتَوَضَّأْنَا، فَصَلَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْعَصْرَ بَعْدَ مَا غَرَبَتِ الشَّمْسُ، ثُمَّ صَلَّى بَعْدَهَا الْمَغْرِبَ. (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഉമറുബ്നുൽ ഖത്താബ്(റ) ഖൻദഖ് യുദ്ധ ദിവസം ഖുറൈശികളായ നിഷേധികളെ അധിക്ഷേപിച്ചു. പിന്നെ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, അല്ലാഹുവാണെ! സൂര്യൻ അസ്തമിക്കാറാകും വരെ അസ്ർ നിസ്കരിക്കാൻ എനിക്ക് കഴിഞ്ഞില്ല. നബി(സ) പറഞ്ഞു: "അല്ലാഹുവാണെ! ഞാനും നിസ്കരിച്ചിട്ടില്ല." അങ്ങനെ ഞങ്ങൾ ബുത്ഹാൻ പ്രദേശത്ത് ഇറങ്ങി. നബി(സ)യും ഞങ്ങളും വുളു ചെയ്തു. സൂര്യൻ അസ്തമിച്ച ശേഷമാണ് നബി(സ) അസ്ർ നിസ്കരിച്ചത്. ശേഷം മഗ്രിബും നിസ്കരിച്ചു. (മു)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 328, 328, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُومُ فِي الظُّهْرِ فَيَقْرَأُ قَدْرَ ثَلَاثِينَ آيَةً فِي كُلِّ رَكْعَةٍ، ثُمَّ يَقُومُ فِي الْعَصْرِ فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ قَدْرَ خَمْسَ عَشْرَةَ آيَةً (ن)', 'അബൂസഈദിൽ ഖുദ്രി(റ): നബി(സ) ളുഹ്റിൽ ഓരോ റക്അത്തിലും മുപ്പത് ആയത്തുകൾ ഓതുന്നത്ര സമയം നിൽക്കുമായിരുന്നു. അസ്ർ നിസ്കാരത്തിന്റെ ആദ്യത്തെ രണ്ട് റക്അത്തുകളിൽ പതിനഞ്ച് ആയത്തുകളുടെ സമയം നിന്നിരുന്നു. (ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 328, 328, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا نَحْزُرُ قِيَامَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الظُّهْرِ وَالْعَصْرِ، فَحَزَرْنَا قِيَامَهُ فِي الظُّهْرِ قَدْرَ ثَلَاثِينَ آيَةً، قَدْرَ سُورَةِ السَّجْدَةِ فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ، وَفِي الْأُخْرَيَيْنِ عَلَى النِّصْفِ مِنْ ذَلِكَ، وَحَزَرْنَا قِيَامَهُ فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ مِنَ الْعَصْرِ عَلَى قَدْرِ الْأُخْرَيَيْنِ مِنَ الظُّهْرِ، وَحَزَرْنَا قِيَامَهُ فِي الرَّكْعَتَيْنِ الْأُخْرَيَيْنِ مِنَ الْعَصْرِ عَلَى النِّصْفِ مِنْ ذَلِكَ. (ن)', 'അബൂസഈദിൽ ഖുദ്രി(റ): ഞങ്ങൾ ളുഹ്റിലും അസ്റിലും നബി(സ)യുടെ നിറുത്തത്തെ കണക്കാക്കും. ളുഹ്റിൽ ഏതാണ്ട് മുപ്പത് ആയത്തുകളുടെ സമയമുണ്ട്. ആദ്യ രണ്ട് റക്അത്തിൽ സൂറത്തുസ്സജദ ഓതുന്ന സമയവും പിന്നത്തെ രണ്ടിൽ അതിന്റെ പകുതി ഓതുന്ന സമയവും. അസ്റിന്റെ ആദ്യ രണ്ട് റക്അത്തിൽ ളുഹ്റിന്റെ അവസാനത്തെ രണ്ട് റക്അത്തിന്റെ സമയവും അസ്റിന്റെ അവസാനത്തെ രണ്ടിൽ അതിന്റെ പകുതി സമയവും നിസ്കരിക്കുന്നതായി ഞങ്ങൾ കണക്കാക്കി. (ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 328, 328, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَتَعَاقَبُونَ فِيكُمْ مَلَائِكَةٌ بِاللَّيْلِ وَمَلَائِكَةٌ بِالنَّهَارِ، وَيَجْتَمِعُونَ فِي صَلَاةِ الْفَجْرِ وَصَلَاةِ الْعَصْرِ، ثُمَّ يَعْرُجُ الَّذِينَ بَاتُوا فِيكُمْ، فَيَسْأَلُهُمْ وَهُوَ أَعْلَمُ بِهِمْ: كَيْفَ تَرَكْتُمْ عِبَادِي؟ فَيَقُولُونَ: تَرَكْنَاهُمْ وَهُمْ يُصَلُّونَ وَأَتَيْنَاهُمْ وَهُمْ يُصَلُّونَ. (خ)', 'അബുഹുറൈറ(റ): തിരുമേനി(സ) പറഞ്ഞു: രാത്രിയും പകലും മലക്കുകൾ നിങ്ങളുടെ അടുക്കലേക്ക് ഊഴമിട്ടു വന്നു കൊണ്ടുരിക്കും. അസ്ർ നിസ്കാരവേളയിലും സുബ്ഹ് നിസ്കാര വേളയിലും അവർ സമ്മേളിക്കും. നിങ്ങളോടൊപ്പം താമസിച്ചിരുന്നവർ മേൽപ്പോട്ടു കയറിപ്പോകും. അല്ലാഹു അവരോടു ചോദിക്കും. എന്റെ ദാസന്മാരെ വിട്ടുപോരുമ്പോൾ അവരുടെ സ്ഥിതി എന്തായിരുന്നു? - യഥാർത്ഥത്തിൽ, ആ ദാസന്മാരെ സംബന്ധിച്ചു അല്ലാഹുവാണ് ഏറ്റവും അറിവുള്ളവൻ - മലക്കുകൾ പറയും: അവർ നിസ്കരിച്ചു കൊണ്ടിരിക്കെയാണ് ഞങ്ങൾ അവരെ വിട്ടു പോന്നത്. ഞങ്ങൾ അവരുടെ അടുക്കൽ ചെന്നപ്പോഴും അവർ നിസ്കാരത്തിൽ തന്നെയായിരുന്നു. (ബു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 328, 329, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ جَرِيرٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَنَظَرَ إِلَى الْقَمَرِ لَيْلَةً فَقَالَ: إِنَّكُمْ سَتَرَوْنَ رَبَّكُمْ كَمَا تَرَوْنَ هَذَا الْقَمَرَ لَا تُضَامُونَ فِي رُؤْيَتِهِ فَإِنِ اسْتَطَعْتُمْ أَنْ لَا تُغْلَبُوا عَلَى صَلَاةٍ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا فَافْعَلُوا، ثُمَّ قَرَأَ: {وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ الْغُرُوبِ} . (خ)', 'ജരീർ(റ): ഞങ്ങൾ പ്രവാചക(സ)നോടൊന്നിച്ചായിക്കെ, ചന്ദ്രനെ നോക്കിക്കൊണ്ട് തുമുമേനി പറഞ്ഞു: "നിശ്ചയം ഈ ചന്ദ്രനെ നിങ്ങൾ കാണുന്നതു പോലെ നിങ്ങളുടെ നാഥനെ നിങ്ങൾ വഴിയെ ദർശിക്കും. ആ ദർശനത്തിൽ യാതൊരു (സംശയവും) അവ്യക്തതയും ഉണ്ടായിരിക്കുകയില്ല. അതുകൊണ്ട് സൂര്യോദയത്തിന് മുമ്പും, സൂര്യാസ്തമയത്തിന് മുമ്പും ഉള്ള നിസ്കാരം നിർവ്വഹിക്കാൻ കഴിഞ്ഞെങ്കിൽ അതു നിങ്ങൾ നിർവ്വഹിച്ചു കൊള്ളുക". ഇങ്ങനെ പറഞ്ഞ ശേഷം ''നിന്റെ നാഥന്റെ മഹത്വത്തെയും പരിശുദ്ധിയെയും സൂര്യോദയത്തിനു മുമ്പും സൂര്യാസ്തമയത്തിനു മുമ്പും പ്രകീർത്തിച്ചു കൊള്ളക്'' എന്ന ഖുർആൻ വാക്യം തിരുമേനി(സ) എടുത്തുദ്ധരിച്ചു. (ബു)', 'جَرِيرٍ', 'ജരീർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, 'സംശയവും', 329, 329, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنَّا نُصَلِّي الْمَغْرِبَ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ نَرْمِي فَيَرَى أَحَدُنَا مَوْضِعَ نَبْلِهِ. (ق,د,ن,جه)', 'അനസുബ്നു മാലിക്(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പം മഗ്രിബ് നിസ്കരിച്ചു. ശേഷം ഞങ്ങൾ അമ്പെയ്താൽ തന്റെ അമ്പിന്റെ പതനസ്ഥലം കാണാനാകുമായിരുന്നു. (ബു,മു,ദ,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 329, 329, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ سَلَمَةَ بْنِ الْأَكْوَعِ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الْمَغْرِبَ سَاعَةَ تَغْرُبُ الشَّمْسُ، إِذَا غَابَ حَاجِبُهَا. (ق,د,ت,جه)', 'സലമതുബ്നു അഖ്വഅ്(റ): നബി(സ) മഗ്രിബ് നിസ്കരിച്ചിരുന്നത് സൂര്യൻ അസ്തമിച്ച് അതിന്റെ പ്രകാശം മറഞ്ഞുകഴിഞ്ഞ നേരത്തായിരുന്നു. (ബു,മു,ദ,തു,ജ)', 'سَلَمَةَ بْنِ الْأَكْوَعِ', 'സലമതുബ്നു അഖ്വഅ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 329, 329, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ مَرْثَدٍ ابْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا قَدِمَ عَلَيْنَا أَبُو أَيُّوبَ غَازِيًا وَعُقْبَةُ بْنُ عَامِرٍ يَوْمَئِذٍ عَلَى مِصْرَ، فَأَخَّرَ الْمَغْرِبَ، فَقَامَ إِلَيْهِ أَبُو أَيُّوبَ فَقَالَ لَهُ: مَا هَذِهِ الصَّلَاةُ يَا عُقْبَةُ؟ فَقَالَ: شُغِلْنَا، قَالَ: أَمَا سَمِعْتَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا تَزَالُ أُمَّتِي بِخَيْرٍ - أَوْ قَالَ: عَلَى الْفِطْرَةِ - مَا لَمْ يُؤَخِّرُوا الْمَغْرِبَ إِلَى أَنْ تَشْتَبِكَ النُّجُومُ". (د,جه)', 'മർസദുബ്നു അബ്ദില്ല(റ): അബൂഅയ്യൂബ്(റ) യോദ്ധാവായിരിക്കെ ഞങ്ങളിലേക്ക് വന്നപ്പോൾ ഉഖ്ബതുബ്നു ആമിർ ഈജിപ്തിലുണ്ടായിരുന്നു. അദ്ദേഹം മഗ്രിബ് പിന്തിച്ചു. അപ്പോൾ അബൂഅയ്യൂബ് കടന്നുവന്നു ചോദിച്ചു: ഇത് ഏത് നിസ്കാരമാണ് ഉഖ്ബാ? അദ്ദേഹം പറഞ്ഞു: ഞങ്ങൾ ജോലിത്തിരക്കിലായിരുന്നു. അബൂഅയ്യൂബ്(റ) പറഞ്ഞു: "എന്റെ ജനത നക്ഷത്രങ്ങൾ കോർത്ത് മഗ്രിബ് പിന്തിക്കാത്തിടത്തോളം കാലം നന്മയിലായിരിക്കും." എന്ന് നബി(സ) പറയുന്നത് നിങ്ങൾ കേട്ടിട്ടില്ലേ? (ദ,ജ)', 'مَرْثَدٍ ابْنِ عَبْدِ اللهِ', 'മർസദുബ്നു അബ്ദില്ല(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 329, 329, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ حَسَّانَ بْنِ بِلَالٍ رَضِيَ اللهُ عَنْهُمَا: عَنْ رَجُلٍ مِنْ أَسْلَمَ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُمْ كَانُوا يُصَلُّونَ مَعَ نَبِيِّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمَغْرِبَ، ثُمَّ يَرْجِعُونَ إِلَى أَهَالِيهِمْ إِلَى أَقْصَى الْمَدِينَةِ يَرْمُونَ وَيُبْصِرُونَ مَوَاقِعَ سِهَامِهِمْ. (ن)', 'ഹസ്സാനുബ്നു ബിലാൽ(റ), നബി(സ)യുടെ സഹാബികളിൽ പെട്ടവനും അസ്ലം ഗോത്രക്കാരനുമായ ഒരാളിൽ നിന്ന്: അവർ (സഹാബികൾ) നബി(സ)യോടൊത്ത് മഗ്രിബ് നിസ്കരിക്കാറുണ്ടായിരുന്നു. പിന്നെ മദീനയുടെ പ്രാന്തപ്രദേശങ്ങളിലുള്ള അവരുടെ കുടുംബത്തിലേക്ക് തിരിച്ചുപോകും. അപ്പോൾ അമ്പെയ്യുകയും അതിന്റെ പതനസ്ഥലം അവർ കാണുകയും ചെയ്യാറുണ്ടായിരുന്നു. (ന)', 'حَسَّانَ بْنِ بِلَالٍ', 'ഹസ്സാനുബ്നു ബിലാൽ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 330, 330, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُ - يَرْفَعُهُ أَحْيَانًا وَأَحْيَانًا لَا يَرْفَعُهُ - قَالَ: "وَقْتُ صَلَاةِ الظُّهْرِ مَا لَمْ تَحْضُرِ الْعَصْرُ، وَوَقْتُ صَلَاةِ الْعَصْرِ مَا لَمْ تَصْفَرَّ الشَّمْسُ، وَوَقْتُ الْمَغْرِبِ مَا لَمْ يَسْقُطْ فَوْرُ الشَّفَقِ، وَوَقْتُ الْعِشَاءِ مَا لَمْ يَنْتَصِفِ اللَّيْلُ، وَوَقْتُ الصُّبْحِ مَا لَمْ تَطْلُعِ الشَّمْسُ". (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): (ഈ ഹദീസ് ചിലപ്പോൾ ഇത് നബി(സ) പറഞ്ഞിരിക്കുന്നു എന്ന് പറഞ്ഞ് നബിയിലേക്ക് ചേർത്തും, മറ്റുചിലപ്പോൾ അല്ലാതെയും പറയാറുണ്ട്.) "ളുഹ്റിന്റെ സമയം അസ്ർ വരെയും അസ്റിന്റെ സമയം സൂര്യൻ മഞ്ഞ വർണ്ണമാകുംവരെയും മഗ്രിബിന്റെ സമയം അസ്തമാന ശോഭ മായുംവരെയും ഇശാഇന്റെ സമയം അർദ്ധരാത്രിവരെയും സുബ്ഹിന്റെ സമയം സൂര്യോദയം വരെയുമാണ്." (ന)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 330, 330, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ سَلَمَةَ بْنِ كُهَيْلٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ سَعِيدَ بْنَ جُبَيْرٍ بِجَمْعٍ أَقَامَ فَصَلَّى الْمَغْرِبَ ثَلَاثَ رَكَعَاتٍ، ثُمَّ أَقَامَ فَصَلَّى الْعِشَاءَ رَكْعَتَيْنِ، ثُمَّ ذَكَرَ أَنَّ ابْنَ عُمَرَ صَنَعَ بِهِمْ مِثْلَ ذَلِكَ فِي ذَلِكَ الْمَكَانِ، وَذَكَرَ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَنَعَ مِثْلَ ذَلِكَ فِي ذَلِكَ الْمَكَانِ. (ن)', 'സലമത്തുബ്നു കുഹൈൽ(റ): ഞാൻ സഈദുബ്നു ജുബൈറിനെ ''ജംഅ്'' (മുസ്ദലിഫ) എന്ന സ്ഥലത്ത് ഇഖാമത്ത് വിളിക്കുന്നതും മഗ്രിബ് മൂന്ന് റക്അത്ത് നിർവ്വഹിക്കുന്നതായും കണ്ടു. പിന്നെ ഇഖാമത്ത് വിളിച്ച് ഇശാ രണ്ട് റക്അത്ത് നിർവ്വഹിച്ചു. പിന്നീട് അദ്ദേഹം പറഞ്ഞു: ഇബ്നുഉമർ(റ) അതേ സ്ഥാനത്തു നിന്ന് ഞങ്ങളോടൊപ്പം ഇങ്ങനെ നിസ്കരിക്കുകയും നബി(സ) തൽ സ്ഥാനത്തു നിന്ന് അപ്രകാരം ചെയ്തിട്ടുണ്ട് എന്ന് പറയുകയും ചെയ്തു. (ന)', 'سَلَمَةَ بْنِ كُهَيْلٍ', 'സലമത്തുബ്നു കുഹൈൽ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 330, 330, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَنَا أَعْلَمُ النَّاسِ بِوَقْتِ هَذِهِ الصَّلَاةِ، كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّيهَا لِسُقُوطِ الْقَمَرِ لِثَالِثَةٍ. (د,ت,ن)', 'നുഅ്മാനുബ്നു ബശീർ(റ): ഈ (ഇശാ) നിസ്കാരത്തിന്റെ സമയത്തെക്കുറിച്ച് ജനങ്ങളിൽ നന്നായി അറിയുന്നവൻ ഞാനാണ്. നബി(സ) അത് നിസ്കരിച്ചിരുന്നത് മൂന്നാം ദിവസം രാത്രി ചന്ദ്രൻ അസ്തമിക്കുന്ന സമയത്തായിരുന്നു. (ദ,തു,ന)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നു ബശീർ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 330, 330, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ أَنْ يُؤَخِّرُوا الْعِشَاءَ إِلَى ثُلُثِ اللَّيْلِ أَوْ نِصْفِهِ". (ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "എന്റെ സമൂഹത്തിന് പ്രയാസകരമാവുകയില്ലായിരുന്നെങ്കിൽ ഞാൻ അവരോട് രാത്രിയുടെ മൂന്നിലൊന്ന് കഴിഞ്ഞോ അല്ലെങ്കിൽ പകുതി കഴിഞ്ഞോ ഇശാ നിസ്കരിക്കാൻ കൽപിക്കുമായിരുന്നു." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 330, 330, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ عَبْد الله بْن عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَكَثْنَا ذَاتَ لَيْلَةٍ نَنْتَظِرُ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِصَلَاةِ الْعِشَاءِ، فَخَرَجَ إِلَيْنَا حِينَ ذَهَبَ ثُلُثُ اللَّيْلِ أَوْ بَعْدَهُ، فَلَا نَدْرِي أَشَيْءٌ شَغَلَهُ أَمْ غَيْرُ ذَلِكَ، فَقَالَ حِينَ خَرَجَ: "أَتَنْتَظِرُونَ هَذِهِ الصَّلَاةَ؟ لَوْلَا أَنْ تَثْقُلَ عَلَى أُمَّتِي لَصَلَّيْتُ بِهِمْ هَذِهِ السَّاعَةَ". ثُمَّ أَمَرَ الْمُؤَذِّنَ فَأَقَامَ الصَّلَاةَ. (د,م)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): ഞങ്ങൾ ഒരു രാത്രിയിൽ നബി(സ)യെ ഇശാ നിസ്കാരത്തിനായി കാത്തിരുന്നു. രാത്രിയുടെ മൂന്നിലൊന്നോ അതിലധികമോ കഴിഞ്ഞപ്പോൾ നബി(സ) ഞങ്ങളുടെ അടുത്തേക്കുവന്നു.നബി(സ) വല്ല ജോലിയിലും ഏർപ്പെട്ടതിനാലാണോ (വൈകാൻ കാരണമായത്) അതോ മറ്റെന്തെങ്കിലും കാരണത്താലാണോ എന്ന് ഞങ്ങൾക്കറിയില്ല. വന്നപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ഈ നിസ്കാരത്തെ പ്രതീക്ഷിച്ചിരിക്കുകയാണോ? എന്റെ സമൂഹത്തിന് പ്രയാസമാകുമായിരുന്നില്ലെങ്കിൽ അവരേയും കൊണ്ട് ഞാൻ ഈ സമയത്ത് നിസ്കരിക്കുമായിരുന്നു." പിന്നെ ഇഖാമത്ത് വിളിക്കാൻ നിർദ്ദേശിക്കുകയും നിസ്കരിക്കുകയും ചെയ്തു. (മു,ദ)', 'عَبْد الله بْن عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['د','م']::text[], array['മു','ദ']::text[], null, null, 331, 331, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ مُعَاذ بْنِ جَبَلٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَبْقَيْنَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي صَلَاةِ الْعَتَمَةِ، فَأَخَّرَ حَتَّى ظَنَّ الظَّانُّ أَنَّهُ لَيْسَ بِخَارِجٍ، وَالْقَائِلُ مِنَّا يَقُولُ: صَلَّى، فَإِنَّا لَكَذَلِكَ حَتَّى خَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالُوا لَهُ كَمَا قَالُوا: فَقَالَ لَهُمْ: "أَعْتِمُوا بِهَذِهِ الصَّلَاةِ، فَإِنَّكُمْ قَدْ فُضِّلْتُمْ بِهَا عَلَى سَائِرِ الْأُمَمِ، وَلَمْ تُصَلِّهَا أُمَّةٌ قَبْلَكُمْ". (د)', 'മുആദുബിനു ജബൽ(റ): ഞങ്ങൾ നബി(സ)യെ ഇശാ നിസ്കാരത്തിനായി കാത്തിരുന്നു. അവിടുന്ന് അത് വളരെ പിന്തിച്ചു. നബി(സ) അതിന് വരികയില്ലാ എന്ന് ആരൊക്കെയോ കരുതി. ഒരാൾ പറഞ്ഞു: അവിടുന്ന് നിസ്കരിച്ചിട്ടുണ്ടാകും. അങ്ങനെയിരിക്കെ നബി(സ) പുറത്ത് വന്നു. അപ്പോൾ അവർ പറഞ്ഞതെല്ലാം നബിയെ അറിയിച്ചു. നബി(സ) അവരോടു പറഞ്ഞു: "നിങ്ങൾ ഈ നിസ്കാരം രാത്രി ഇരുട്ടിയശേഷം നിർവ്വഹിക്കുക. മറ്റു സമുദായത്തേക്കാൾ നിങ്ങൾ ഇതു മുഖേന അനുഗ്രഹീതരായിരിക്കുന്നു. നിങ്ങൾക്ക് മുമ്പുള്ളവരാരും ഇത് നിർവ്വഹിച്ചിട്ടില്ല." (ദ)', 'مُعَاذ بْنِ جَبَلٍ', 'മുആദുബിനു ജബൽ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 331, 331, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَعْتَمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ، حَتَّى ذَهَبَ عَامَّةُ اللَّيْلِ وَحَتَّى نَامَ أَهْلُ الْمَسْجِدِ، ثُمَّ خَرَجَ فَصَلَّى، فَقَالَ: "إِنَّهُ لَوَقْتُهَا، لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي". (م)', 'ആഇശ(റ): രാത്രിയുടെ നല്ലൊരുഭാഗം കഴിയുന്നതുവരെ നബി(സ) ഇശാ പിന്തിച്ചു. പള്ളിയിലെ ആൾക്കാർ ഉറങ്ങിയിരുന്നു. പിന്നെ പുറത്തുവന്ന് നിസ്കരിച്ചു. എന്നിട്ട് പറഞ്ഞു: "ഇതാണ് ഇതിന്റെ സമയം, എന്റ സമുദായത്തിന് ഇത് പ്രയാസകരമാവില്ലെങ്കിൽ." (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 331, 331, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ جَابِرِ بْنِ عَبْدِاللهِ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الظُّهْرَ بِالْهَاجِرَةِ، وَالْعَصْرَ وَالشَّمْسُ نَقِيَّةٌ، وَالْمَغْرِبَ إِذَا وَجَبَتْ، وَالْعِشَاءَ أَحْيَانًا وَأَحْيَانًا، إِذَا رَآهُمْ اجْتَمَعُوا عَجَّلَ، وَإِذَا رَآهُمْ أَبْطَؤُا أَخَّرَ، وَالصُّبْحَ كَانُوا - أَوْ كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّيهَا بِغَلَسٍ. (خ)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നട്ടുച്ചക്കായിരുന്നു നബി(സ) ളുഹ്ർ നിസ്കരിച്ചിരുന്നത്. സൂര്യൻ ശോഭയുള്ളപ്പോഴായിരുന്നു അസ്ർ; സൂര്യൻ അസ്തമിച്ചപ്പോൾ മഗ്രിബും. ഇശാ പലപ്പോഴായി നിർവ്വഹിച്ചു. അഥവാ ജനങ്ങൾ എത്തിച്ചേർന്നാൽ ആദ്യത്തിലും എത്തിയില്ലെങ്കിൽ പിന്തിച്ചും നിർവ്വഹിക്കും. സുബ്ഹ് നേരിയ ഇരുട്ടുള്ളപ്പോഴാണ് നിർവ്വഹിച്ചത്. (ബു)', 'جَابِرِ بْنِ عَبْدِاللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 331, 331, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا سُئِلَ: هَلِ اتَّخَذَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَاتَمًا؟ قَالَ: نَعَمْ، أَخَّرَ لَيْلَةً صَلَاةَ الْعِشَاءِ إِلَى قَرِيبٍ مِنْ شَطْرِ اللَّيْلِ، فَلَمَّا صَلَّى أَقْبَلَ عَلَيْنَا بِوَجْهِهِ فَقَالَ: "إِنَّ النَّاسَ قَدْ صَلَّوْا وَنَامُوا، وَإِنَّكُمْ لَنْ تَزَالُوا فِي صَلَاةٍ مَا انْتَظَرْتُمُ الصَّلَاةَ" قَالَ أَنَسٌ: كَأَنِّي أَنْظُرُ إِلَى وَبِيصِ خَاتَمِهِ. (ن,جه)', 'അനസുബ്നു മാലിക്(റ): അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു: നബി(സ) മോതിരം ധരിച്ചിരുന്നോ?. അദ്ദേഹം പറഞ്ഞു: അതെ, ഒരിക്കൽ ഇശാ നിസ്കാരം എതാണ്ട് രാത്രിയുടെ പകുതിവരെ നബി(സ) പിന്തിച്ചു. നിസ്കാരശേഷം ഞങ്ങളുടെ നേരെനിന്ന് പറഞ്ഞു: "ജനങ്ങൾ നിസ്കരിച്ചു ഉറങ്ങി. നിങ്ങൾ നിസ്കാരം പ്രതീക്ഷിച്ചിരിക്കുമ്പോഴെല്ലാം നിസ്കാരത്തിലാണ്." അനസ്(റ) പറഞ്ഞു: നബി(സ)യുടെ മോതിരത്തിന്റെ തിളക്കം ഞാനിപ്പോഴും കാണുന്നതു പോലെ തോന്നുന്നു. (ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 331, 332, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ عَبْدِاللهِ الْمُزَنِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَغْلِبَنَّكُمُ الْأَعْرَابُ عَلَى اسْمِ صَلَاتِكُمُ الْمَغْرِبِ". قَالَ: وَيَقُولُ الْأَعْرَابُ: هِيَ الْعِشَاءُ. (خ,ن)', 'അബ്ദുല്ലാഹിൽ മുസ്നി(റ): നബി(സ) പറയുന്നു: "അഅ്റാബികൾ (ഉൾപ്രദേശത്തുള്ളവർ) മഗ്രിബ് എന്ന പേരിന്റെ കാര്യത്തിൽ നിങ്ങളെ സ്വാധീനിക്കാതിരിക്കട്ടെ." റിപ്പോർട്ടർ പറഞ്ഞു: അഅ്റാബികൾ പറയുന്നത് അതാണ് ''ഇശാഅ്'' എന്നാണ്. (ബു,ന)', 'عَبْدِاللهِ الْمُزَنِيِّ', 'അബ്ദുല്ലാഹിൽ മുസ്നി(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 332, 332, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَعْتَمَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةً بِالْعِشَاءِ، وَذَلِكَ قَبْلَ أَنْ يَفْشُوَ الْإِسْلَامُ، فَلَمْ يَخْرُجْ حَتَّى قَالَ عُمَرُ: نَامَ النِّسَاءُ وَالصِّبْيَانُ، فَخَرَجَ فَقَالَ لِأَهْلِ الْمَسْجِدِ: "مَا يَنْتَظِرُهَا أَحَدٌ مِنْ أَهْلِ الْأَرْضِ غَيْرُكُمْ". وَفِي رِوَايَةٍ: قَالَتْ: وَكَانُوا يُصَلُّونَ فِيمَا بَيْنَ أَنْ يَغِيبَ الشَّفَقُ إِلَى ثُلُثِ اللَّيْلِ الْأَوَّلِ. (خ)', 'ആഇശ(റ): ഇസ്ലാം പ്രചാരം നേടുന്നതിനുമുമ്പ് ഒരു രാത്രി നബി(സ) ഇശാ നിസ്കാരം നിർവ്വഹിക്കാൻ വളരെ വൈകിയിട്ടും വന്നില്ല. അങ്ങനെ ഉമർ ഇപ്രകാരം വിളിച്ചുപറഞ്ഞു: സ്ത്രീകളും കുട്ടികളും ഉറങ്ങിയിരിക്കുന്നു. അപ്പോൾ നബി(സ) വന്ന് പള്ളിയിലുള്ളവരോട് പറഞ്ഞു: "നിങ്ങളല്ലാതെ ഭൂമിയിലാരും ഇതിനെ പ്രതീക്ഷിക്കുന്നില്ല."⁵ മറ്റൊരു റിപ്പോർട്ടിൽ: ആഇശ(റ) പറഞ്ഞു: ജനങ്ങൾ ഇശാ നിസ്കരിച്ചിരുന്നത് ചുവപ്പ് ശോഭ മാഞ്ഞതിനും രാത്രിയുടെ ആദ്യ മൂന്നിലൊന്നിനും ഇടയിലായിരുന്നു. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 332, 332, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=17 and h.hadith_no=68), 1, 'وَفِي رِوَايَةٍ: قَالَتْ: وَكَانُوا يُصَلُّونَ فِيمَا بَيْنَ أَنْ يَغِيبَ الشَّفَقُ إِلَى ثُلُثِ اللَّيْلِ الْأَوَّلِ. (خ)', 'മറ്റൊരു നിവേദനിൽ: ആഇശ(റ) പറഞ്ഞു: ജനങ്ങൾ ഇശാ നിസ്കരിച്ചിരുന്നത് ചുവപ്പ് ശോഭ മാഞ്ഞതിനും രാത്രിയുടെ ആദ്യ മൂന്നിലൊന്നിനും ഇടയിലായിരുന്നു. (ബു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَخَّرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْعِشَاءَ ذَاتَ لَيْلَةٍ حَتَّى ذَهَبَ مِنَ اللَّيْلِ، فَقَامَ عُمَرُ رَضِيَ اللهُ عَنْهُ فَنَادَى: الصَّلَاةَ يَا رَسُولَ اللهِ! رَقَدَ النِّسَاءُ وَالْوِلْدَانُ، فَخَرَجَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالْمَاءُ يَقْطُرُ مِنْ رَأْسِهِ وَهُوَ يَقُولُ: "إِنَّهُ الْوَقْتُ، لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ഒരു രാത്രിയിൽ കുറേ സമയം കഴിയുംവരെ ഇശാ പിന്തിച്ചു. അപ്പോൾ ഉമർ എഴുന്നേറ്റ് നിസ്കാരത്തെക്കുറിച്ച് ഉണർത്തിയിട്ട് പറഞ്ഞു: നബിയേ, സ്ത്രീകളും കുട്ടികളും ഉറങ്ങിയിരിക്കുന്നു. അപ്പോൾ നബി(സ) പുറത്തുവന്നു. നബിയുടെ തലയിൽ നിന്നും വെള്ളം ഇറ്റിവീഴുന്നുണ്ടായിരുന്നു. നബി(സ) പറഞ്ഞു. "ഇതാണ് യഥാർത്ഥ സമയം, എന്റെ സമൂഹത്തിന് പ്രയാസകരമല്ലെങ്കിൽ". (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 332, 332, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُؤَخِّرُ الْعِشَاءَ الْآخِرَةَ. (ن)', 'ജാബിറുബ്നു സമുറ(റ): നബി(സ) ഇശാ നിസ്കാരം പിന്തിക്കാറുണ്ടായിരുന്നു. (ന)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 332, 332, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِتَأْخِيرِ الْعِشَاءِ وَبِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ. (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "എന്റെ സമുദായത്തിന് പ്രയാസകരമല്ലായിരുന്നുവെങ്കിൽ ഇശാ പിന്തിക്കാനും എല്ലാ നിസ്കാരത്തിനും പല്ല് തേക്കാനും ഞാനവരോട് കൽപിക്കുമായിരുന്നു." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', '⁵. രാത്രിയിൽ വൈകി പ്രാർത്ഥനക്ക് കാത്തിരിക്കുന്ന രീതി മുൻ സമുദായങ്ങളിലില്ല.', null, array['ن']::text[], array['ന']::text[], null, null, 332, 332, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّى بِنَا رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الْمَغْرِبِ، ثُمَّ لَمْ يَخْرُجْ إِلَيْنَا حَتَّى ذَهَبَ شَطْرُ اللَّيْلِ، فَخَرَجَ فَصَلَّى بِهِمْ، ثُمَّ قَالَ: "إِنَّ النَّاسَ قَدْ صَلَّوْا وَنَامُوا، وَأَنْتُمْ لَمْ تَزَالُوا فِي صَلَاةٍ مَا انْتَظَرْتُمُ الصَّلَاةَ، وَلَوْلَا ضَعْفُ الضَّعِيفِ وَسَقَمُ السَّقِيمِ لَأَمَرْتُ بِهَذِهِ الصَّلَاةِ أَنْ تُؤَخَّرَ إِلَى شَطْرِ اللَّيْلِ". (د,ن,جه)', 'അബൂസഈദിൽ ഖുദ്രി(റ): നബി(സ) ഞങ്ങളെയുമായി മഗ്രിബ് നിസ്കരിച്ചു. പിന്നെ രാത്രിയുടെ ഒരു ഭാഗം കഴിയും വരെ ഞങ്ങളിലേക്ക് വന്നില്ല. പിന്നീട് വന്ന് നിസ്കരിച്ചശേഷം പറഞ്ഞു: "ജനങ്ങൾ നിസ്കരിച്ചു കഴിഞ്ഞ് ഉറങ്ങിയിരിക്കുന്നു. നിങ്ങൾ നിസ്കാരം പ്രതീക്ഷിച്ചിരിക്കുമ്പോഴെല്ലാം നിസ്കാരത്തിലാണ്. രോഗിയുടെ രോഗവും ദുർബ്ബലന്റെ ദൗർബല്യവും ഇല്ലായിരുന്നെങ്കിൽ ഈ നിസ്കാരം അർദ്ധരാത്രിയിലേക്കു നീട്ടാൻ ഞാൻ കൽപിക്കുമായിരുന്നു." (ദ,ന,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 332, 333, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ أَنَا وَأَصْحَابِي الَّذِينَ قَدِمُوا مَعِي فِي السَّفِينَةِ نُزُولًا فِي بَقِيعِ بُطْحَانَ وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْمَدِينَةِ، فَكَانَ يَتَنَاوَبُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ صَلَاةِ الْعِشَاءِ كُلَّ لَيْلَةٍ نَفَرٌ مِنْهُمْ، فَوَافَقْنَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَا وَأَصْحَابِي، وَلَهُ بَعْضُ الشُّغْلِ فِي بَعْضِ أَمْرِهِ، فَأَعْتَمَ بِالصَّلَاةِ حَتَّى ابْهَارَّ اللَّيْلُ، ثُمَّ خَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَصَلَّى بِهِمْ، فَلَمَّا قَضَى صَلَاتَهُ قَالَ لِمَنْ حَضَرَهُ: "عَلَى رِسْلِكُمْ! أُبْشِرُوا، إِنَّ مِنْ نِعْمَةِ اللهِ عَلَيْكُمْ أَنَّهُ لَيْسَ أَحَدٌ مِنَ النَّاسِ يُصَلِّي هَذِهِ السَّاعَةَ غَيْرُكُمْ - أَوْ قَالَ - مَا صَلَّى هَذِهِ السَّاعَةَ أَحَدٌ غَيْرُكُمْ" لَا يَدْرِي أَيَّ الْكَلِمَتَيْنِ قَالَ، قَالَ أَبُو مُوسَى: فَرَجَعْنَا فَفَرِحْنَا بِمَا سَمِعْنَا مِنْ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (خ)', 'അബൂമൂസ(റ): ഞാനും എന്നോടൊപ്പം കപ്പലിൽ വന്ന എന്റെ കൂട്ടുകാരും ബുത്ഹാൻ താഴ്വരയിൽ ഇറങ്ങി. നബി(സ) അപ്പോൾ മദീനയിലായിരുന്നു. ഇശാ നിസ്കാരത്തിന് ഓരോ രാത്രിയും അവരിലെ ഓരോ സംഘം മാറിമാറി നബി(സ)യോടൊപ്പം ഉണ്ടാകുമായിരുന്നു. അങ്ങനെ ഞാനും എന്റെ കൂട്ടുകാരും നബി(സ)യോടൊപ്പം ചേർന്നു. നബി(സ) ചില കാര്യങ്ങളിൽ വ്യാപൃതനായതിനാൽ നിസ്കാരം രാത്രിയുടെ അന്ത്യത്തിലേക്ക് പിന്തിച്ചു. പിന്നെ വന്ന് അവരോടൊപ്പം നിസ്കരിച്ചു. നിസ്കാര ശേഷം അവിടെയുള്ളവരോടായി പറഞ്ഞു: "നിങ്ങൾ സാവകാശം കാണിക്കുക (ശ്രദ്ധിക്കുക). നിങ്ങൾ സന്തോഷ വാർത്ത അറിയുക. നിങ്ങളല്ലാതാരും ഈ സമയത്ത് നിസ്കരിക്കുന്നില്ല." "നിങ്ങളല്ലാതെ ആരും ഈ സമയത്ത് നിസ്കരിച്ചിട്ടില്ല." -ഏതു പദമാണ് നബി(സ) പറഞ്ഞതെന്ന് അദ്ദേഹം സംശയിക്കുന്നു.- അബൂമൂസ(റ) പറഞ്ഞു: "അല്ലാഹു നിങ്ങൾക്ക് നൽകിയ അനുഗ്രഹങ്ങളിൽപെട്ടതാണ് ഇത്.." എന്ന നബി(സ)യുടെ വാക്കു കേട്ട് സന്തോഷത്തോടെയാണ് ഞങ്ങൾ പിരിഞ്ഞുപോയത്. (ബു)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 333, 333, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ أَبِي بَرْزَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَكْرَهُ النَّوْمَ قَبْلَ الْعِشَاءِ وَالْحَدِيثَ بَعْدَهَا. (ق,د,ت,ن,جه)', 'അബൂബർസ(റ): ഇശാ നിസ്കാരത്തിനു മുമ്പ് ഉറങ്ങുന്നതും അതിനുശേഷം സംസാരിക്കുന്നതും നബി(സ) വെറുത്തിരുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي بَرْزَةَ', 'അബൂബർസ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 333, 333, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْمُرُ مَعَ أَبِي بَكْرٍ فِي الْأَمْرِ مِنْ أَمْرِ الْمُسْلِمِينَ وَأَنَا مَعَهُمَا. (ت,ن)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ): നബി(സ) അബൂബക്കറി(റ)നൊപ്പം മുസ്ലിംകളുടെ കാര്യങ്ങളിൽ രാത്രി ചർച്ചയിൽ ഏർപ്പെടുമായിരുന്നു. അവരോടൊപ്പം ഞാനുമുണ്ടാവാറുണ്ട്. (തു,ന)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 333, 333, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الصَّلَاةِ بَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ، وَعَنِ الصَّلَاةِ بَعْدَ الصُّبْحِ حَتَّى تَطْلُعَ الشَّمْسُ. (م,ن)', 'അബൂഹുറൈറ(റ): അസ്റിനുശേഷം സൂര്യൻ അസ്തമിക്കും വരെയും സുബ്ഹിക്കുശേഷം സൂര്യൻ ഉദിക്കും വരെയും നിസ്കരിക്കുന്നത് നബി(സ) വിലക്കിയിരിക്കുന്നു.⁶ (മു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 334, 334, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: شَهِدَ عِنْدِي رِجَالٌ مَرْضِيُّونَ، وَأَرْضَاهُمْ عِنْدِي عُمَرُ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الصَّلَاةِ بَعْدَ الصُّبْحِ حَتَّى تُشْرِقَ الشَّمْسُ، وَبَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ. (خ,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): സുബ്ഹിക്കു ശേഷം സൂര്യൻ ഉദിക്കുന്നതു വരെയും അസ്റിനുശേഷം സൂര്യൻ അസ്തമിക്കുന്നതു വരെയും നിസ്കരിക്കുന്നത് നബി(സ) നിരോധിച്ചിരിക്കുന്നുവെന്ന് ഇഷ്ടപ്പെട്ട ചില വ്യക്തികൾ എന്റെ അടുത്ത് സാക്ഷ്യപ്പെടുത്തി. അവരിൽ എനിക്കേറ്റവും ഇഷ്ടപ്പെട്ടവൻ ഉമറാണ്. (ബു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 334, 334, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَحَرَّوْا بِصَلَاتِكُمْ طُلُوعَ الشَّمْسِ وَلَا غُرُوبَهَا". (خ,ن)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "ഉദയത്തിന്റെയും അസ്തമയത്തിന്റെയും സമയത്തേക്ക് നിങ്ങൾ നിസ്കാരത്തെ കാത്തുവെക്കരുത്." (ബു,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 334, 334, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'قَالَ ابْنُ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا طَلَعَ حَاجِبُ الشَّمْسِ فَأَخِّرُوا الصَّلَاةَ حَتَّى تَرْتَفِعَ، وَإِذَا غَابَ حَاجِبُ الشَّمْسِ، فَأَخِّرُوا الصَّلَاةَ حَتَّى تَغِيبَ". (خ)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "സൂര്യൻ മറ നീക്കി പുറത്തു വരുമ്പോൾ അത് ഉയരുന്നതുവരെ നിങ്ങൾ നിസ്കാരം പിന്തിക്കുക. സൂര്യൻ മറക്കുള്ളിൽ അപ്രത്യക്ഷമാകുമ്പോൾ അത് മറയുന്നതുവരെ നിസ്കാരം പിന്തിക്കുക". (ബു)', null, 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 334, 334, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ بَيْعَتَيْنِ وَعَنْ لِبْسَتَيْنِ، وَعَنْ صَلَاتَيْنِ: نَهَى عَنِ الصَّلَاةِ بَعْدَ الْفَجْرِ حَتَّى تَطْلُعَ الشَّمْسُ، وَبَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ، وَعَنِ اشْتِمَالِ الصَّمَّاءِ، وَعَنِ الاحتباء في ثوب واحد يُفْضِي بفرجه إِلَى السَّمَاءِ، وَعَنِ الْمُنَابَذَةِ وَالْمُلَامَسَةِ. (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) രണ്ടുതരം ധന കൈമാറ്റങ്ങളേയും രണ്ടുതരം വസ്ത്രധാരണത്തേയും രണ്ട് നിസ്കാരങ്ങളേയും നിരോധിച്ചിരിക്കുന്നു; ഫജ്റിനു ശേഷം സൂര്യൻ ഉദിച്ചുയരും വരെയും, അസ്റിനുശേഷം സൂര്യൻ മറയും വരെയുമുള്ള നിസ്കാരം നബി(സ) നിരോധിച്ചു. നെഞ്ചും കൈകളുമെല്ലാം ഉള്ളിലാക്കി ഒരൊറ്റ വസ്ത്രം കൊണ്ട് മൂടിപ്പുതക്കുന്നതും, കണങ്കാലുകൾ കുത്തിനിറുത്തി ചന്തി നിലത്തൂന്നി ഗുഹ്യസ്ഥാനം നഗ്നമാക്കി ഒരൊറ്റ വസ്ത്രം കൊണ്ട് ശരീരം മൂടുന്നതും നിരോധിച്ചു. ഇന്നതിന്മേൽ തൊട്ടാൽ തൊട്ട ആൾക്ക് ആ സാധനം കിട്ടുമെന്ന് വ്യവസ്ഥ ചെയ്യുന്നതും, ഇന്ന സാധനം ഇന്ന വിധത്തിൽ എറിഞ്ഞാൽ ആ സാധനം മൽസരത്തിൽ പങ്കെടുത്തവന് ലഭിക്കുമെന്ന് വ്യവസ്ഥ ചെയ്യുന്നതും നിരോധിച്ചു. (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', '⁶. ഉദയാസ്തമയങ്ങളിൽ പ്രത്യേക കാരണങ്ങളില്ലാതെ നിസ്കാരം കറാഹത്താണ്.', null, array['خ']::text[], array['ബു']::text[], null, null, 334, 334, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ أَبِي عَبْد الله عَبْد الرَّحْمَن بْنِ عَسِيلَةَ الصُّنَابِحِيِّ رَضِيَ اللهُ عَنْهُمْ: أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الشَّمْسُ تَطْلُعُ وَمَعَهَا قَرْنُ الشَّيْطَانِ، فَإِذَا ارْتَفَعَتْ فَارَقَهَا، فَإِذَا اسْتَوَتْ قَارَنَهَا فَإِذَا زَالَتْ فَارَقَهَا، فَإِذَا دَنَتْ لِلْغُرُوبِ قَارَنَهَا، فَإِذَا غَرُبَتْ فَارَقَهَا". وَنَهَى رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الصَّلَاةِ فِي تِلْكَ السَّاعَاتِ. (ن,جه)', 'അബൂഅബ്ദില്ല അബ്ദുർറഹ്മാനുബ്നു അസീല(റ): നബി(സ) പറഞ്ഞു: "സൂര്യൻ ഉദിക്കുമ്പോൾ അതിന്റെ കൂടെ പിശാചിന്റെ കൊമ്പുമുണ്ടാകും,⁷ സൂര്യൻ ഉയർന്നാൽ കൊമ്പ് വേർപ്പെടുന്നു. നേരെ കുത്തനെ വരുമ്പോൾ കൊമ്പ് കൂടിച്ചേരുന്നു. സൂര്യൻ മധ്യത്തിൽ നിന്ന് തെറ്റിയാൽ വേർപ്പെടുന്നു. അസ്തമയത്തോടടുക്കുമ്പോൾ കൊമ്പ് വരുന്നു, അസ്തമിച്ചാൽ വേർപ്പെടുന്നു." നബി(സ) ആ സമയങ്ങളിൽ നിസ്കാരം വിലക്കിയിരിക്കുന്നു. (ന,ജ)', 'أَبِي عَبْد الله عَبْد الرَّحْمَن بْنِ عَسِيلَةَ الصُّنَابِحِيِّ', 'അബൂഅബ്ദില്ല അബ്ദുർറഹ്മാനുബ്നു അസീല(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 334, 335, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا صَلَاةَ بَعْدَ الْفَجْرِ حَتَّى تَبْزُغَ الشَّمْسُ، وَلَا صَلَاةَ بَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ". (ن)', 'അബൂസഈദിൽ ഖുദ്രി(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഫജ്റിനു ശേഷം സൂര്യൻ ഉദിച്ചുയരുന്നതു വരെ നിസ്കാരമില്ല. അസ്റിനു ശേഷം സൂര്യൻ അസ്തമിക്കുന്നതു വരെയും നിസ്കാരമില്ല." (ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 335, 335, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنْ عَمْرو بْنِ عَبَسَةَ رَضِيَ اللهُ عَنْهُ قَالَ : قُلْتُ : يَا رَسُولَ اللهِ! هَلْ مِنْ سَاعَةٍ أَقْرَبُ مِنَ الْأُخْرَى؟، أَوْ هَلْ مِنْ سَاعَةٍ يُبْتَغَى ذِكْرُهَا؟ قَالَ : "نَعَمْ، إِنَّ أَقْرَبَ مَا يَكُونُ الرَّبُّ عَزَّ وَجَلَّ مِنَ الْعَبْدِ جَوْفَ اللَّيْلِ الْآخِرِ، فَإِنِ اسْتَطَعْتَ أَنْ تَكُونَ مِمَّنْ يَذْكُرُ اللهَ عَزَّ وَجَلَّ فِي تِلْكَ السَّاعَةِ فَكُنْ، فَإِنَّ الصَّلَاةَ مَحْضُورَةٌ مَشْهُودَةٌ إِلَى طُلُوعِ الشَّمْسِ، فَإِنَّهَا تَطْلُعُ بَيْنَ قَرْنَيِ الشَّيْطَانِ، وَهِيَ سَاعَةُ صَلَاةِ الْكُفَّارِ، فَدَعِ الصَّلَاةَ حَتَّى تَرْتَفِعَ قِيدَ رُمْحٍ وَيَذْهَبَ شُعَاعُهَا، ثُمَّ الصَّلَاةُ مَحْضُورَةٌ مَشْهُودَةٌ حَتَّى تَعْتَدِلَ الشَّمْسُ اعْتِدَالَ الرُّمْحِ بِنِصْفِ النَّهَارِ، فَإِنَّهَا سَاعَةٌ تُفْتَحُ فِيهَا أَبْوَابُ جَهَنَّمَ وَتُسْجَرُ، فَدَعِ الصَّلَاةَ حَتَّى يَفِيءَ الْفَيْءُ، ثُمَّ الصَّلَاةُ مَحْضُورَةٌ مَشْهُودَةٌ حَتَّى تَغِيبَ الشَّمْسُ، فَإِنَّهَا تَغِيبُ بَيْنَ قَرْنَيْ شَيْطَانٍ، وَهِيَ صَلَاةُ الْكُفَّارِ". (ن)', 'അംറുബ്നു അബസ(റ): ഞാൻ ചോദിച്ചു. പ്രവാചകരേ! ഏതെങ്കിലും സമയം മറ്റു സമയത്തേക്കാൾ അല്ലാഹുവുമായി കൂടുതൽ അടുത്തതായിട്ടുണ്ടോ? അല്ലെങ്കിൽ അവന്റെ അനുഗ്രഹത്തെ പ്രതീക്ഷിക്കാവുന്ന വല്ല സമയവും? നബി(സ) പറഞ്ഞു: "അതെ! ഒരടിമയുമായി നാഥൻ ഏറ്റവും അടുക്കുന്നത് രാത്രിയുടെ അന്ത്യയാമത്തിലാണ്. അല്ലാഹുവിനെ സ്മരിക്കുന്നവരുടെ കൂട്ടത്തിൽ ആ സമയത്ത് നിനക്ക് ഉൾപ്പെടാൻ കഴിയുമെങ്കിൽ അപ്രകാരം ചെയ്യുക. തീർച്ചയായും സൂര്യോദയം വരെ നിസ്കാരം (മലക്കുകൾ) സാക്ഷിയാവുന്നതും (അല്ലാഹുവിന്റെ മുമ്പിൽ) ഹാജരാക്കപ്പെടുന്നതുമായിരിക്കും. സൂര്യൻ ഉദിച്ചുയരുന്നത് ചെകുത്താന്റെ കൊമ്പുകൾക്കിടയിലാണ്. അത് നിഷേധികളുടെ നിസ്കാര സമയമാണ്. ഒരു കുന്തത്തിന്റെ അത്രയും ഉയരും വരെയും അതിന്റെ ജ്വാല മായുംവരെയും നിസ്കാരം ഉപേക്ഷിക്കുക. പിന്നെ സൂര്യൻ പകലിന്റെ മധ്യത്തിൽ ഒരു കുന്തത്തിന് സമമാകുന്നതുവരെ നിസ്കാരം സാക്ഷി നിൽക്കപ്പെടുന്നതും ഹാജരാക്കപ്പെടുന്നതുമായിരിക്കും. നരക കവാടങ്ങൾ തുറക്കപ്പെടുന്നതും നരകം കത്തിയെരിയുന്നതുമായ സമയമാണത്. അതിനാൽ ചൂട് കുറയുന്നതു വരെ നിസ്കാരം ഉപേക്ഷിക്കുക. പിന്നെ സൂര്യൻ മറയുന്നതുവരെ നിസ്കാരം ഹാജരാക്കപ്പെടുന്നതും സാക്ഷിയാക്കപ്പെടുന്നതുമായിരിക്കും. അത് മറയുന്നത് പിശാചിന്റെ കൊമ്പുകൾക്കിടയിലാണ്. അത് നിഷേധികളുടെ പ്രാർത്ഥനാ സമയമാണ്.'' (ന)', 'عَمْرو بْنِ عَبَسَةَ', 'അംറുബ്നു അബസ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 335, 335, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ رَضِيَ اللهُ عَنْهُ يَقُولُ : ثَلَاثُ سَاعَاتٍ كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَ سَلَّمَ يَنْهَانَا أَنْ نُصَلِّيَ فِيهِنَّ أَوْ أَنْ نَقْبُرَ فِيهِنَّ مَوْتَانَا، حِينَ تَطْلُعُ الشَّمْسُ بَازِغَةً حَتَّى تَرْتَفِعَ وَ حِينَ يَقُومُ قَائِمُ الظَّهِيرَةِ حَتَّى تَمِيلَ الشَّمْسُ، وَحِينَ تَضَيَّفُ الشَّمْسُ لِلْغُرُوبِ حَتَّى تَغْرُبَ. (م,ن)', 'ഉഖ്ബതുബ്നു ആമിറുൽ ജുഹനി(റ): മൂന്ന് സമയങ്ങളിൽ ഞങ്ങൾ നിസ്കരിക്കുന്നതും മരിച്ചവരെ മറമാടുന്നതും നബി(സ) വിലക്കിയിരിക്കുന്നു; സൂര്യൻ ഉദിച്ചുയരുമ്പോൾ, അതൽപം ഉയരുന്നതുവരെ, സൂര്യൻ നേരെ മുകളിലാവുമ്പോൾ അത് അൽപം തെറ്റുന്നതുവരെ, സൂര്യൻ അസ്തമയത്തോടടുത്താൽ അത് അസ്തമിക്കും വരെ. (മു,ന)', 'عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ', 'ഉഖ്ബതുബ്നു ആമിറുൽ ജുഹനി(റ)', '⁷, കൊമ്പുകൊണ്ടുദ്ദേശ്യം സ്വാധീനമെന്നാവാം. ഈ സമയങ്ങൾ പിശാചിന്റെ ഉത്തേജക സമയങ്ങളാണെന്നുകാണാം. സൂര്യാരാധകർ ഈ സമയങ്ങളിൽ സൂര്യപൂജ നടത്താറുണ്ട്.', null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 335, 336, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ مُعَاوِيَةَ رَضِيَ اللهُ عَنْهُ قَالَ: إِنَّكُمْ لَتُصَلُّونَ صَلَاةً، لَقَدْ صَحِبْنَا رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَمَا رَأَيْنَاهُ يُصَلِّيهَا، وَلَقَدْ نَهَى عَنْهُمَا، يَعْنِي الرَّكْعَتَيْنِ بَعْدَ الْعَصْرِ. (خ)', 'മുആവിയ(റ): നിങ്ങൾ നിസ്കരിച്ചു കൊണ്ടിരിക്കുന്ന ഈ നിസ്കാരം ഞങ്ങൾ നബി(സ)യോടൊപ്പം സഹവസിച്ചിരുന്നപ്പോഴൊന്നും നബി(സ) നിർവ്വഹിച്ചതായി കണ്ടിട്ടില്ല. അത് നിരോധിക്കുകയാണ് ചെയ്തത്. അഥവാ അസ്റിനു ശേഷമുള്ള രണ്ട് റക്അത്ത്. (ബു)', 'مُعَاوِيَةَ', 'മുആവിയ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 336, 336, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الصَّلَاةِ بَعْدَ الْعَصْرِ، إِلَّا أَنْ تَكُونَ الشَّمْسُ بَيْضَاءَ نَقِيَّةً مُرْتَفِعَةً. (ن)', 'അലി(റ): നബി(സ) അസ്റിനു ശേഷം നിസ്കരിക്കുന്നത് നിരോധിച്ചു. സൂര്യൻ കിരണങ്ങൾ തെളിഞ്ഞു മുകളിൽ നിൽക്കുവോളമല്ലാതെ. (ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 336, 336, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: صَلَاتَانِ مَا تَرَكَهُمَا رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَيْتِي قَطُّ سِرًّا وَلَا عَلَانِيَةً: رَكْعَتَيْنِ قَبْلَ الْفَجْرِ وَرَكْعَتَيْنِ بَعْدَ الْعَصْرِ. (خ,ن)', 'ആഇശ(റ): എന്റെ വീട്ടിലായിരിക്കെ രണ്ട് റക്അത്തുകൾ നബി(സ) രഹസ്യമായോ പരസ്യമായോ ഒഴിവാക്കിയിരുന്നില്ല. ഫജ്റിനു മുമ്പുള്ള രണ്ട് റക്അത്തും, അസ്റിനു ശേഷമുള്ള രണ്ട് റക്അത്തും.(ബു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 336, 336, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: وَالَّذِي ذَهَبَ بِهِ مَا تَرَكَهُمَا حَتَّى لَقِيَ اللهَ، وَمَا لَقِيَ اللهَ تَعَالَى حَتَّى ثَقُلَ عَنِ الصَّلَاةِ، وَكَانَ يُصَلِّي كَثِيرًا مِنْ صَلَاتِهِ قَاعِدًا تَعْنِي الرَّكْعَتَيْنِ بَعْدَ الْعَصْرِ وَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّيهِمَا وَلَا يُصَلِّيهِمَا فِي الْمَسْجِدِ مَخَافَةَ أَنْ يُثْقِلَ عَلَى أُمَّتِهِ، وَكَانَ يُحِبُّ مَا يُخَفِّفُ عَنْهُمْ. (خ)', 'ആഇശ(റ): അല്ലാഹുവാണെ! നബി(സ) അല്ലാഹുവിനെ അഭിമുഖീകരിക്കുന്നതു (വഫാത്താകും) വരെ ആ രണ്ടും ഉപേക്ഷിച്ചിട്ടില്ല. നിസ്കാരം നിർവ്വഹിക്കൽ പ്രയാസമാകുന്നതു വരെ അദ്ദേഹം വഫാത്തായിട്ടുമില്ല. അസ്റിനു ശേഷമുള്ള ആ രണ്ട് റക്അത്തുകൾ അദ്ദേഹം അധികവും ഇരുന്നാണ് നിസ്കരിച്ചിരുന്നത്. ആ രണ്ടു റക്അത്തുകൾ നബി(സ) നിസ്കരിക്കാറുണ്ടായിരുന്നു. എന്നാൽ അവരണ്ടും തന്റെ സമുദായത്തിന് വിഷമകരമായേക്കുമെന്നു ഭയപ്പെട്ടതിനാൽ പള്ളിയിൽ വെച്ച് നിസ്കരിക്കാറില്ല. അവർക്ക് പ്രയാസം കുറഞ്ഞവയാണ് നബി(സ) ഇഷ്ടപ്പെട്ടിരുന്നത്. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 336, 336, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنْ أَبِي سَلَمَةَ رَضِيَ اللهُ عَنْهَا: أَنَّهُ سَأَلَ عَائِشَةَ عَنِ السَّجْدَتَيْنِ اللَّتَيْنِ كَانَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّيهِمَا بَعْدَ الْعَصْرِ، فَقَالَتْ: إِنَّهُ كَانَ يُصَلِّيهِمَا قَبْلَ الْعَصْرِ، ثُمَّ إِنَّهُ شُغِلَ عَنْهُمَا أَوْ نَسِيَهُمَا، فَصَلَّاهُمَا بَعْدَ الْعَصْرِ، وَكَانَ إِذَا صَلَّى صَلَاةً أَثْبَتَهَا. (ن)', 'അബൂസലമ(റ): നബി(സ) അസ്റിനു ശേഷം നിർവ്വഹിക്കാറുള്ള രണ്ട് റക്അത്തുകളെക്കുറിച്ച് അദ്ദേഹം ആഇശ(റ)യോട് ചോദിച്ചപ്പോൾ ആഇശ(റ) പറഞ്ഞു: നബി(സ) അത് അസ്റിനു മുമ്പാണ് നിർവ്വഹിച്ചിരുന്നത്. പിന്നീട് നബി(സ) അത് മറന്നു പോവുകയോ ജോലിയിലാവുകയോ ചെയ്തപ്പോൾ അസ്റിനു ശേഷമാണ് നിർവ്വഹിച്ചത്. നബി(സ) ഒരു നിസ്കാരം നിർവ്വഹിച്ചാൽ അത് സ്ഥിരപ്പെടുത്തുന്നതാണ്. (ന)', 'أَبِي سَلَمَةَ', 'അബൂസലമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 336, 336, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى فِي بَيْتِهَا بَعْدَ الْعَصْرِ رَكْعَتَيْنِ مَرَّةً وَاحِدَةً، وَأَنَّهَا ذَكَرَتْ ذَلِكَ لَهُ، فَقَالَ: "هُمَا رَكْعَتَانِ كُنْتُ أُصَلِّيهِمَا بَعْدَ الظُّهْرِ، فَشُغِلْتُ عَنْهُمَا حَتَّى صَلَّيْتُ الْعَصْرَ". (ن)', 'ഉമ്മുസലമ(റ): നബി(സ) അവരുടെ വീട്ടിൽ വെച്ച് ഒരിക്കൽ മാത്രം അസ്റിനുശേഷം രണ്ട് റക്അത്ത് നിർവ്വഹിച്ചു. അവർ അതിനെക്കുറിച്ച് നബിയോട് അന്വേഷിച്ചപ്പോൾ നബി(സ) പറഞ്ഞു: "അതു ഞാൻ ളുഹ്റിനുശേഷം നിർവ്വഹിക്കാറുള്ള രണ്ട് റക്അത്താണ്. അസ്ർ നിസ്കരിക്കുന്നതു വരെ ഞാൻ മറ്റൊരു ജോലിയിൽ വ്യാപൃതനായി." (ന)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 336, 337, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: إِنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي رَكْعَتَيْنِ قَبْلَ الْعَصْرِ،فَشُغِلَ عَنْهُمَا فَرَكَعَهُمَاحِينَ غَابَتِ الشَّمْسُ،فَلَمْ أَرَهُ يُصَلِّيهِمَا قَبْلُ وَلَابَعْدُ. (ق,د,ن)', 'ഉമ്മുസലമ(റ): നബി(സ) അസ്റിന്റെ മുമ്പ് രണ്ട് റക്അത്ത് നിർവ്വഹിക്കാറുണ്ടായിരുന്നു. അങ്ങനെ (അത് നിർവ്വഹിക്കാൻ കഴിയാത്തവിധം) വ്യാപൃതനായി. സൂര്യൻ അസ്തമിക്കുന്ന സമയത്താണ് അത് പിന്നീട് നിർവ്വഹിച്ചത്. നബി(സ) അതിനു മുമ്പോ ശേഷമോ അങ്ങനെ നിസ്കരിക്കുന്നത് ഞാൻ കണ്ടിട്ടില്ല. (ബു,മു,ദ,ന)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 337, 337, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ حَفْصَةَ رَضِيَ اللهُ عَنْهَا أَنَّهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا طَلَعَ الْفَجْرُ لَا يُصَلِّي إِلَّا رَكْعَتَيْنِ خَفِيفَتَيْنِ. (ق,ن)', 'ഹഫ്സ(റ): പ്രഭാതം ഉദിച്ചാൽ ലഘുവായ രണ്ട് റക്അത്തല്ലാതെ നബി(സ) നിസ്കരിക്കാറില്ല. (ബു,മു,ന)', 'حَفْصَةَ', 'ഹഫ്സ(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 337, 337, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ عَمْرِو بْنِ عَبَسَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا رَسُولَ اللهِ! مَنْ أَسْلَمَ مَعَكَ؟ قَالَ: "حُرٌّ وَعَبْدٌ" قُلْتُ: هَلْ مِنْ سَاعَةٍ أَقْرَبُ إِلَى اللهِ عَزَّ وَجَلَّ مِنْ أُخْرَى؟ قَالَ: "نَعَمْ، جَوْفُ اللَّيْلِ الْآخِرُ، فَصَلِّ مَا بَدَا لَكَ حَتَّى تُصَلِّيَ الصُّبْحَ، ثُمَّ انْتَهِ حَتَّى تَطْلُعَ الشَّمْسُ وَمَا دَامَتْ كَأَنَّهَا حَجَفَةٌ حَتَّى تَنْتَشِرَ، ثُمَّ صَلِّ مَا بَدَا لَكَ حَتَّى تَقُومَ الْعَمُودُ عَلَى ظِلِّهِ، ثُمَّ انْتَهِ حَتَّى تَزُولَ الشَّمْسُ، فَإِنَّ جَهَنَّمَ تُسْجَرُ نِصْفَ النَّهَارِ، ثُمَّ صَلِّ مَا بَدَا لَكَ حَتَّى تُصَلِّيَ الْعَصْرَ، ثُمَّ انْتَهِ حَتَّى تَغْرُبَ الشَّمْسُ، فَإِنَّهَا تَغْرُبُ بَيْنَ قَرْنَيْ شَيْطَانٍ وَتَطْلُعُ بَيْنَ قَرْنَيْ شَيْطَانٍ". (ن)', 'അംറുബ്നു അബസ(റ): ഞാൻ നബി(സ)യുടെ അടുക്കൽ ചെന്നു ചോദിച്ചു. അല്ലാഹുവിന്റെ ദൂതരേ! ആരാണ് താങ്കളോടൊപ്പം മുസ്ലിമായത്? നബി(സ) പറഞ്ഞു: "ഒരു അടിമയും ഒരു സ്വതന്ത്രനും." പിന്നെ ഞാൻം ചോദിച്ചു: ഏതെങ്കിലും സമയം അല്ലാഹുവുമായി കൂടുതൽ അടുക്കുന്നതായിട്ടുണ്ടോ? നബി(സ) പറഞ്ഞു: "അതെ, രാത്രിയുടെ അന്ത്യയാമം. അപ്പോൾ സുബ്ഹ് നിസ്കാരം വരെ നിനക്ക് കഴിയുന്നത്ര നിസ്കരിക്കുക. പിന്നെ സൂര്യൻ ഉദിച്ചുയരുകയും ഒരു പരിചപോലെ പൂർണ്ണമാകുകയും ചെയ്യുന്നതു വരെ നിസ്കാരത്തിൽ നിന്നും വിരമിക്കുക. പിന്നെ ഒരു വസ്തു അതിന്റെ നിഴലിൽ ആകുന്നതുവരെ (ഉച്ചവരെ) നിസ്കരിക്കുക. പിന്നീട് സൂര്യൻ തെറ്റുന്നതുവരെ വിരമിക്കുക. കാരണം മധ്യാഹ്ന സമയം നരകം കത്തിക്കപ്പെടും. പിന്നെ നീ അസ്ർ നിസ്കരിക്കുന്നതുവരെ നിനക്ക് കഴിയുന്നത്ര നിസ്കരിക്കുക. സൂര്യൻ അസ്തമിക്കുന്നതുവരെ പിന്നീട് നിസ്കാരം പാടില്ല. കാരണം അത് ഉദിക്കുന്നതും അസ്തമിക്കുന്നതും പിശാചിന്റെ കൊമ്പുകൾക്കിടയിലാണ്." (ന)', 'عَمْرِو بْنِ عَبَسَةَ', 'അംറുബ്നു അബസ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 337, 337, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ جُبَيْرِ بْنِ مُطْعِمٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَا بَنِي عَبْدِ مَنَافٍ! لَا تَمْنَعُوا أَحَدًا طَافَ بِهَذَا الْبَيْتِ وَصَلَّى أَيَّةَ سَاعَةٍ شَاءَ مِنْ لَيْلٍ أَوْ نَهَارٍ". (ن)', 'ജുബൈറുബ്നുമുത്ഇം(റ): നബി(സ) പറഞ്ഞു: "അബ്ദു മനാഫിന്റെ മക്കളേ! ഈ ഗേഹത്തെ (കഅ്ബ) പ്രദക്ഷിണം ചെയ്യുന്നതിൽ നിന്നും നിസ്കരിക്കുന്നതിൽ നിന്നും രാത്രിയിലോ പകലിലോ ഏത് സമയത്തും ആരെയും നിങ്ങൾ തടയരുത്." (ന)', 'جُبَيْرِ بْنِ مُطْعِمٍ', 'ജുബൈറുബ്നുമുത്ഇം(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 337, 337, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ عَبْد اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَأَلْتُ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيُّ الْعَمَلِ أَحَبُّ إِلَى اللهِ تَعَالَى؟ قَالَ: "الصَّلَاةُ عَلَى وَقْتِهَا، وَبِرُّ الْوَالِدَيْنِ، وَالْجِهَادُ فِي سَبِيلِ اللهِ عَزَّ وَجَلَّ". (ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ഞാൻ നബി(സ)യോട് ചോദിച്ചു: അല്ലാഹുവിന് ഏറ്റവും ഇഷ്ടപ്പെട്ട കർമ്മം ഏതാണ്? നബി(സ) പറഞ്ഞു: "കൃത്യസമയത്തെ നിസ്കാരം, മാതാപിതാക്കൾക്ക് ഗുണം ചെയ്യൽ, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ സമരം ചെയ്യൽ." (ന)', 'عَبْد اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 338, 338, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَأَلْتُ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيُّ الْعَمَلِ أَحَبُّ إِلَى اللهِ عَزَّ وَجَلَّ؟ قَالَ: "إِقَامُ الصَّلَاةِ لِوَقْتِهَا". (ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ഞാൻ നബി(സ)യോട് ചോദിച്ചു: ഏത് കർമ്മമാണ് അല്ലാഹുവിന് ഏറെ ഇഷ്ടകരം? നബി(സ) പറഞ്ഞു: "നിസ്കാരം കൃത്യ സമയത്ത് നിലനിർത്തൽ." (ന)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 338, 338, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ أُمِّ فَرْوَةَ رَضِيَ اللهُ عَنْهَا- وَكَانَتْ مِمَّنْ بَايَعَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَتْ: سُئِلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَيُّ الْأَعْمَالِ أَفْضَلُ؟ قَالَ: "الصَّلَاةُ لِأَوَّلِ وَقْتِهَا". (د,ت)', 'നബിയുമായി ബൈഅത്ത് ചെയ്തവരിൽപ്പെട്ട ഉമ്മുഫർവ(റ): നബി(സ)യോട് ചോദിക്കപ്പെട്ടു: അല്ലാഹുവിന് ഏറ്റവും ഇഷ്ടപ്പെട്ട കർമ്മം ഏതാണ്? നബി(സ) പറഞ്ഞു: "നിസ്കാരം അതിന്റെ ആദ്യ സമയത്ത് നിർവ്വഹിക്കുക." (ദ,തു)', 'أُمِّ فَرْوَةَ', 'നബിയുമായി ബൈഅത്ത് ചെയ്തവരിൽപ്പെട്ട ഉമ്മുഫർവ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 338, 338, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ مُحَمَّدِ بْنِ الْمُنْتَشِرِ رَضِيَ اللهُ عَنْهُ أَنَّهُ كَانَ فِي مَسْجِدِ عَمْرِو بْنِ شُرَحْبِيلَ، فَأُقِيمَتِ الصَّلَاةُ فَجَعَلُوا يَنْتَظِرُونَهُ، فَقَالَ: إِنِّي كُنْتُ أُوتِرُ. قَالَ: وَسُئِلَ عَبْدُ اللهِ: هَلْ بَعْدَ الْأَذَانِ وِتْرٌ؟ قَالَ: نَعَمْ، وَبَعْدَ الْإِقَامَةِ، وَحَدَّثَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ نَامَ عَنِ الصَّلَاةِ حَتَّى طَلَعَتِ الشَّمْسُ ثُمَّ صَلَّى. (ن)', 'മുഹമ്മദുബ്നുൽ മുൻതശിർ(റ): അദ്ദേഹം അംറുബ്നു ശുറഹ്ബീലിന്റെ പള്ളിയിലായിരിക്കെ ഇഖാമത്ത് വിളിക്കപ്പെട്ടു. അവർ അദ്ദേഹത്തെ പ്രതീക്ഷിച്ചിരിക്കുകയായിരുന്നു. അദ്ദേഹം പറഞ്ഞു: ഞാൻ വിത്ർ നിസ്കരിക്കുകയായിരുന്നു. അപ്പോൾ അബ്ദുല്ലയോട് ചോദിച്ചു.⁸ ബാങ്കിനു ശേഷം വിത്ർ നിർവ്വഹിക്കാമോ? അദ്ദേഹം പ്രതിവചിച്ചു: അതെ, ഇഖാമത്തിനു ശേഷവും ഉണ്ട്. അദ്ദേഹം നബി(സ)യിൽ നിന്ന് ഉദ്ധരിച്ചു: നബി(സ) നിസ്കരിക്കാതെ സൂര്യൻ ഉദിക്കും വരെ ഉറങ്ങിപ്പോയി. പിന്നെ നിസ്കരിച്ചു. (ന)', 'مُحَمَّدِ بْنِ الْمُنْتَشِرِ', 'മുഹമ്മദുബ്നുൽ മുൻതശിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 338, 338, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُ: "يَا عَلِيُّ! ثَلَاثٌ لَا تُؤَخِّرْهَا؛ الصَّلَاةُ إِذَا آنَتْ، وَالْجَنَازَةُ إِذَا حَضَرَتْ، وَالْأَيِّمُ إِذَا وَجَدْتَ لَهَا كُفْئًا". (ت,جه)', 'അലി(റ): നബി(സ) അദ്ദേഹത്തോടു പറഞ്ഞു: "അലീ! മൂന്ന് കാര്യങ്ങൾ പിന്തിക്കരുത്; സമയമായാൽ നിസ്കാരം, ജനാസ ഹാജരായാൽ, കന്യകക്ക് അനുയോജ്യനായ വരനെ ലഭിച്ചാൽ." (തു,ജ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 338, 338, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا صَلَّى رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَاةً لِوَقْتِهَا الْآخِرِ مَرَّتَيْنِ حَتَّى قَبَضَهُ اللهُ. (ت)', 'ആഇശ(റ): നബി(സ) മരണം വരെ നിസ്കാരം അതിന്റെ അവസാന സമയത്ത് രണ്ടു തവണ നിസ്കരിച്ചിട്ടില്ല. (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', '⁸. സുബ്ഹ് ബാങ്ക് കൊടുക്കുമ്പോൾ വിത്റ് നിസ്കരിക്കാമോ എന്നാണ് സംശയം. നേരത്തെ നിർവ്വഹിക്കാൻ കഴിഞ്ഞിട്ടില്ലെങ്കിൽ ആകാമെന്നാണ് ശുറഹ്ബീൽ പ്രവർത്തിയിലൂടെ വ്യക്തമാക്കുന്നത്.', null, array['ت']::text[], array['തു']::text[], null, null, 338, 338, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللهُ عَنْهُ قَالَ: أَشْهَدُ أَنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "خَمْسُ صَلَوَاتٍ افْتَرَضَهُنَّ اللهُ تَعَالَى، مَنْ أَحْسَنَ وُضُوءَهُنَّ، وَصَلَّاهُنَّ لِوَقْتِهِنَّ، وَأَتَمَّ رُكُوعَهُنَّ وَخُشُوعَهُنَّ، كَانَ لَهُ عَلَى اللهِ عَهْدٌ أَنْ يَغْفِرَ لَهُ، وَمَنْ لَمْ يَفْعَلْ فَلَيْسَ لَهُ عَلَى اللهِ عَهْدٌ، إِنْ شَاءَ غَفَرَ لَهُ، وَإِنْ شَاءَ عَذَّبَهُ". (د,ن)', 'ഉബാദതുബ്നു സ്വാമിത്(റ): നബി(സ) പറയുന്നതായി കേട്ടുവെന്ന് ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു: "അഞ്ചു നേരത്തെ നിസ്കാരം അല്ലാഹു നിർബന്ധമാക്കിയിരിക്കുന്നു. ആരെങ്കിലും നന്നായി വുദു ചെയ്ത് യഥാസമയം നിസ്കരിച്ചാൽ, അതിലെ റുകൂഉം ഭക്തിയും പൂർണ്ണമാക്കിയാൽ അയാൾക്ക് പൊറുത്തു കൊടുക്കുക എന്നത് അല്ലാഹുവിന്റെ കരാറാണ്. ആർ അപ്രകാരം ചെയ്യുന്നില്ലയോ അത്തരക്കാർക്ക് ഈ കരാർ ബാധകമല്ല. അവനുദ്ദേശിച്ചാൽ അവന് പൊറുത്തുകൊടുക്കും. അവനുദ്ദേശിച്ചാൽ അവനെ ശിക്ഷിക്കും." (ദ,ന)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദതുബ്നു സ്വാമിത്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 339, 339, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ فَضَالَةَ رَضِيَ اللهُ عَنْهُ قَالَ: عَلَّمَنِي رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَكَانَ فِيمَا عَلَّمَنِي "وَحَافِظْ عَلَى الصَّلَوَاتِ الْخَمْسِ". قَالَ: قُلْتُ: إِنَّ هَذِهِ سَاعَاتٌ لِي فِيهَا أَشْغَالٌ، فَمُرْنِي بِأَمْرٍ جَامِعٍ إِذَا أَنَا فَعَلْتُهُ أَجْزَأَ عَنِّي، فَقَالَ: "حَافِظْ عَلَى الْعَصْرَيْنِ". وَمَا كَانَتْ مِنْ لُغَتِنَا، فَقُلْتُ: وَمَا الْعَصْرَانِ؟ فَقَالَ: صَلَاةٌ قَبْلَ طُلُوعِ الشَّمْسِ، وَصَلَاةٌ قَبْلَ غُرُوبِهَا". (د)', 'ഫളാല(റ): നബി(സ) എന്നെ പഠിപ്പിച്ചതിൽപ്പെട്ടതാണ്: "നീ അഞ്ചു നേരത്തെ നിസ്കാരം നിലനിർത്തുക." അദ്ദേഹം (ഫളാല) തുടർന്നു പറയുന്നു: ഇത് എനിക്ക് ധാരാളം ജോലികളുള്ള സമയങ്ങളായതിനാൽ കൂടുതൽ അനുയോജ്യമായതും അത് പ്രവർത്തിച്ചാൽ എനിക്കുപകരം മതിയാകുന്ന രീതിയിലുള്ളതുമായ ഒരു കാര്യം എന്നെ അറിയിച്ചാലും. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ രണ്ട് അസ്റുകൾ നിലനിർത്തുക." ആ പ്രയോഗം ഞങ്ങളുടെ ഭാഷയിലില്ല. ഞാൻ ചോദിച്ചു: ഏതാണ് രണ്ട് അസ്റുകൾ? നബി(സ) പ്രതിവചിച്ചു: "സൂര്യോദയത്തിനു മുമ്പുള്ള നിസ്കാരവും, അസ്തമയത്തിനു മുമ്പുള്ള നിസ്കാരവും."⁹ (ദ)', 'فَضَالَةَ', 'ഫളാല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 339, 339, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "خَمْسٌ مَنْ جَاءَ بِهِنَّ مَعَ إِيمَانٍ دَخَلَ الْجَنَّةَ؛ مَنْ حَافَظَ عَلَى الصَّلَوَاتِ الْخَمْسِ عَلَى وُضُوئِهِنَّ وَرُكُوعِهِنَّ وَسُجُودِهِنَّ وَمَوَاقِيتِهِنَّ، وَصَامَ رَمَضَانَ، وَحَجَّ الْبَيْتَ إِنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا، وَأَعْطَى الزَّكَاةَ طَيِّبَةً بِهَا نَفْسُهُ، وَأَدَّى الْأَمَانَةَ، قَالُوا: يَا أَبَا الدَّرْدَاءِ! وَمَا أَدَاءُ الْأَمَانَةِ؟ قَالَ: الْغُسْلُ مِنَ الْجَنَابَةِ. (د)', 'അബൂദ്ദർദാഅ്(റ): നബി(സ) പറഞ്ഞു: "വിശ്വാസപൂർവ്വം അഞ്ച് കാര്യങ്ങൾ ആർ പ്രവർത്തിക്കുന്നുവോ അവർ സ്വർഗ്ഗസ്ഥരാണ്. അതായത്, അഞ്ച് നേരത്തെ നിസ്കാരം വുദുവോടും റുകൂഓടും സൂജൂദോടും കൂടി അതിന്റെ സമയത്ത് നിർവ്വഹിക്കുകയും, റമദാനിൽ നോമ്പനുഷ്ഠിക്കുകയും, കഴിവുള്ളപ്പോൾ ഹജ്ജ് ചെയ്യുകയും, സകാത്ത് നൽകി ശരീരസംസ്കരണം നേടുകയും, ബാധ്യതകൾ നിറവേറ്റുകയും ചെയ്യലാണവ." ആളുകൾ ചോദിച്ചു: ''അബൂദ്ദർദാഅ്! എന്താണ് ബാധ്യതകൾ നിറവേറ്റൽ? അപ്പോൾ പറഞ്ഞു: ജനാബത്തുണ്ടായാൽ കുളിക്കലാണത്. (ദ)', 'أَبِي الدَّرْدَاءِ', 'അബൂദ്ദർദാഅ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 339, 339, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ لِي رَسُولُ اللهِ: "كَيْفَ أَنْتَ إِذَا كَانَتْ عَلَيْكَ أُمَرَاءُ يُؤَخِّرُونَ الصَّلَاةَ عَنْ وَقْتِهَا؟ - أَوْ - يُمِيتُونَ الصَّلَاةَ عَنْ وَقْتِهَا؟" قَالَ: قُلْتُ: فَمَا تَأْمُرُنِي؟ قَالَ: "صَلِّ الصَّلَاةَ لِوَقْتِهَا، فَإِنْ أَدْرَكْتَهَا مَعَهُمْ فَصَلِّ، فَإِنَّهَا لَكَ نَافِلَةٌ". (م,د)', 'അബൂദർറ്(റ): നബി(സ) എന്നോടു ചോദിച്ചു: "നിസ്കാരം അതിന്റെ സമയത്തിൽ നിന്നും പിന്തിക്കുന്ന നേതാക്കളാണുള്ളതെങ്കിൽ (അല്ലെങ്കിൽ) നിസ്കാരം അതിന്റെ സമയത്തെവിട്ട് നിർജ്ജീവമാക്കുന്നവരാണുള്ളതെങ്കിൽ നീ എന്തുചെയ്യും?." ഞാൻ ചോദിച്ചു: അങ്ങെന്താണ് എന്നോട് കൽപ്പിക്കുന്നത്? നബി(സ) പറഞ്ഞു: "നീ നിസ്കാരം അതിന്റെ സമയത്ത് നിർവ്വഹിക്കുക. അവരോടൊപ്പം നിസ്കാരം ലഭിച്ചാൽ അതും നിർവ്വഹിക്കുക. അതു നിനക്ക് സുന്നത്തായി പരിഗണിക്കപ്പെടും". (മു,ദ)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', '⁹. സുബ്ഹി, മഗ്രിബ് നിസ്കാരങ്ങൾ സമയത്ത് തന്നെ നിർവ്വഹിക്കണമെന്ന്.', null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 339, 340, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ لِي رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا أَبَا ذَرٍّ إِنَّهُ سَيَكُونُ بَعْدِي أُمَرَاءُ يُمِيتُونَ الصَّلَاةَ، فَصَلِّ الصَّلَاةَ لِوَقْتِهَا فَإِنْ صَلَّيْتَ لِوَقْتِهَا كَانَتْ لَكَ نَافِلَةً، وَإِلَّا كُنْتَ قَدْ أَحْرَزْتَ صَلَاتَكَ". (م,د,ت,ن,جه)', 'അബൂദർറ്(റ): നബി(സ) എന്നോട് പറഞ്ഞു: "ഹേ അബൂദർറ്, എനിക്കു ശേഷമുള്ള ഭരണാധികാരികൾ നിസ്കാരം നിർജ്ജീവമാക്കും. അപ്പോൾ നീ നിസ്കാരം അതിന്റെ സമയത്തു നിർവ്വഹിക്കുക. സമയത്ത് നിർവ്വഹിച്ച ശേഷം അവരോടൊപ്പവും നിർവ്വഹിച്ചാൽ ആദ്യത്തേത് സുന്നത്തായി പരിഗണിക്കപ്പെടും. നിർവ്വഹിക്കാത്തപക്ഷം നീ നിസ്കാരത്തിന്റെ സമയം പാഴാക്കിയവനാകും". (മു,ദ,തു,ന,ജ)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 340, 340, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ عَمْرِو بْنِ مَيْمُونٍ الْأَوْدِي رَضِيَ اللهُ عَنْهُ قَالَ: قَدِمَ عَلَيْنَا مُعَاذُ بْنُ جَبَلٍ الْيَمَنَ - رَسُولُ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - إِلَيْنَا، قَالَ: فَسَمِعْتُ تَكْبِيرَهُ مَعَ الْفَجْرِ، رَجُلٌ أَجَشُّ الصَّوْتِ قَالَ: فَأُلْقِيَتْ عَلَيْهِ مَحَبَّتِي، فَمَا فَارَقْتُهُ حَتَّى دَفَنْتُهُ بِالشَّامِ مَيِّتًا، ثُمَّ نَظَرْتُ إِلَى أَفْقَهِ النَّاسِ بَعْدَهُ، فَأَتَيْتُ ابْنَ مَسْعُودٍ فَلَزِمْتُهُ حَتَّى مَاتَ، فَقَالَ: قَالَ لِي رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "كَيْفَ بِكُمْ إِذَا أَتَتْ عَلَيْكُمْ أُمَرَاءُ يُصَلُّونَ الصَّلَاةَ لِغَيْرِ مِيقَاتِهَا؟" قُلْتُ: فَمَا تَأْمُرُنِي إِنْ أَدْرَكَنِي ذَلِكَ يَا رَسُولَ اللهِ؟ قَالَ: "صَلِّ الصَّلَاةَ لِمِيقَاتِهَا، وَاجْعَلْ صَلَاتَكَ مَعَهُمْ سُبْحَةً". (د,جه)', 'അംറുബ്നുമൈമൂനുൽ ഔദീ(റ): നബി(സ)യുടെ ദൂതനായി മുആദുബ്നു ജബൽ(റ) യമനിൽ ഞങ്ങളുടെയടുക്കൽ വന്നു. അദ്ദേഹം ഫജ്ർ നിസ്കാരത്തിൽ തക്ബീർ ചൊല്ലുന്നത് ഞാൻ കേട്ടു. ഘനഗംഭീരമായ ശബ്ദമുള്ള ആളായിരുന്നു അദ്ദേഹം. അദ്ദേഹത്തോടെനിക്ക് സ്നേഹം വർദ്ധിച്ചു. പിന്നീട് അദ്ദേഹത്തെ ശാമിൽ മറമാടുംവരെ ഞാൻ വേർപിരിഞ്ഞിരുന്നില്ല. അദ്ദേഹത്തിന്റെ കാലശേഷം (ദീനിൽ) അവഗാഹമുള്ള ആളുകളെ ഞാൻ അന്വേഷിച്ചു. അങ്ങനെ ഇബ്നുമസ്ഊദി(റ)നോടൊപ്പം അദ്ദേഹത്തിന്റ മരണംവരെ ഞാൻ കൂടെയുണ്ടായിരുന്നു. അദ്ദേഹം പറഞ്ഞു: നബി(സ) എന്നോട് പറഞ്ഞു: "നിസ്കാരം കൃത്യസമയത്ത് നിർവ്വഹിക്കാത്ത ഭരണാധികാരികൾ നിങ്ങൾക്ക് വരുമ്പോൾ നിങ്ങളുടെ നിലപാട് എന്തായിരിക്കും?" ഞാൻ ചോദിച്ചു: പ്രവാചകരേ! അങ്ങനെ ഒരവസ്ഥ നേരിട്ടാൽ എന്തുചെയ്യണമെന്നാണ് താങ്കൾ കൽപ്പിക്കുന്നത്? നബി(സ) പറഞ്ഞു: "നീ നിസ്കാരം അതിന്റെ സമയത്തു നിർവ്വഹിക്കുക. അവരോടൊപ്പമുള്ള നിന്റെ നിസ്കാരം ഐച്ഛികമാക്കുകയും ചെയ്യുക." (ദ,ജ)', 'عَمْرِو بْنِ مَيْمُونٍ الْأَوْدِي', 'അംറുബ്നുമൈമൂനുൽ ഔദീ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 340, 340, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّهَا سَتَكُونُ عَلَيْكُمْ بَعْدِي أُمَرَاءُ، تَشْغَلُهُمْ أَشْيَاءُ عَنِ الصَّلَاةِ لِوَقْتِهَا حَتَّى يَذْهَبَ وَقْتُهَا، فَصَلُّوا الصَّلَاةَ لِوَقْتِهَا". فَقَالَ رَجُلٌ: يَا رَسُولَ اللهِ! أُصَلِّي مَعَهُمْ؟ قَالَ: "نَعَمْ، إِنْ شِئْتَ". (د)', 'ഉബാദത്തുബ്നു സ്വാമിത്(റ): നബി(സ) പറഞ്ഞു: "എനിക്കുശേഷം നിങ്ങൾക്ക് ചില ഭരണാധികാരികൾ ഉണ്ടാകും. നിസ്കാരത്തിന്റെ സമയത്ത് അത് നിർവ്വഹിക്കാതെ മറ്റുകാര്യങ്ങളിൽ അവർ വ്യാപൃതരായിരിക്കും. അങ്ങനെ നിസ്കാര സമയം കഴിയും. അതിനാൽ നിങ്ങൾ നിസ്കാരം അതിന്റെ സമയത്തു നിർവ്വഹിക്കുക." അപ്പോൾ ഒരാൾ ചോദിച്ചു: പ്രവാചകരേ! ഞാൻ അവരോടൊന്നിച്ചു നിസ്കരിക്കേണ്ടതുണ്ടോ? "അതെ, നീ ഉദ്ദേശിച്ചാൽ." (ദ)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദത്തുബ്നു സ്വാമിത്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 340, 340, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ قَبِيصَةَ بْنِ وَقَّاصٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَكُونُ عَلَيْكُمْ أُمَرَاءُ مِنْ بَعْدِي يُؤَخِّرُونَ الصَّلَاةَ، فَهِيَ لَكُمْ وَهِيَ عَلَيْهِمْ، فَصَلُّوا مَعَهُمْ مَا صَلَّوُا الْقِبْلَةَ". (د)', 'ഖബീസതുബ്നു വഖാസ(റ): നബി(സ) പറഞ്ഞു: "എനിക്കു ശേഷം നിസ്കാരം പിന്തിക്കുന്ന ഭരണാധികാരികൾ നിങ്ങൾക്കുണ്ടാവും. അപ്പോൾ നിങ്ങൾക്ക് അത് അനുകൂലവും അവർക്ക് പ്രതികൂലവും ആയിത്തീരും. അവർ ഖിബ്ലക്കു നേരെ തിരിഞ്ഞു നിസ്കരിക്കുന്നേടത്തോളം നിങ്ങൾ അവരോടൊപ്പം നിസ്കരിക്കുക." (ദ)', 'قَبِيصَةَ بْنِ وَقَّاصٍ', 'ഖബീസതുബ്നു വഖാസ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 340, 341, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: سُئِلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الرَّجُلِ يَغْفُلُ عَنِ الصَّلَاةِ أَوْ يَرْقُدُ عَنْهَا، قَالَ: "يُصَلِّيهَا إِذَا ذَكَرَهَا". (ن,جه)', 'അനസ്ബുനു മാലിക്(റ): നിസ്കാരം മറക്കുകയോ ഉറങ്ങിപ്പോകുകയോ ചെയ്യുന്ന ഒരാളെക്കുറിച്ച് നബി(സ)യോട് ചോദിക്കപ്പെട്ടു. അപ്പോൾ പറഞ്ഞു: "ഓർമ്മ വരുമ്പോൾ അവനത് നിർവ്വഹിക്കട്ടെ." (ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്ബുനു മാലിക്(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 341, 341, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ نَسِيَ صَلَاةً فَلْيُصَلِّهَا إِذَا ذَكَرَهَا، لَا كَفَّارَةَ لَهَا إِلَّا ذَلِكَ". (م,ت,ن,جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ നിസ്കരിക്കാൻ മറന്നാൽ ഓർമ്മ വന്നയുടൻ അത് നിർവ്വഹിക്കുക. അതല്ലാതെ മറ്റൊരു പ്രായശ്ചിത്തമില്ല." (മു,തു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م','ت','ن','جه']::text[], array['മു','തു','ന','ജ']::text[], null, null, 341, 341, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ قَفَلَ مِنْ غَزْوَةِ خَيْبَرَ سَارَ لَيْلَةً، حَتَّى إِذَا أَدْرَكَهُ الْكَرَى عَرَّسَ، وَقَالَ لِبِلَالٍ: "اكْلَأْ لَنَا اللَّيْلَ" فَصَلَّى بِلَالٌ مَا قُدِّرَ لَهُ، وَنَامَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابُهُ، فَلَمَّا تَقَارَبَ الْفَجْرُ اسْتَنَدَ بِلَالٌ إِلَى رَاحِلَتِهِ مُوَاجِهَ الْفَجْرِ، فَغَلَبَتْ بِلَالًا عَيْنَاهُ وَهُوَ مُسْتَنِدٌ إِلَى رَاحِلَتِهِ، فَلَمْ يَسْتَيْقِظْ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلَا بِلَالٌ وَلَا أَحَدٌ مِنْ أَصْحَابِهِ حَتَّى ضَرَبَتْهُمُ الشَّمْسُ، فَكَانَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوَّلَهُمْ اسْتِيقَاظًا، فَفَزِعَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَيْ بِلَالُ! فَقَالَ بِلَالٌ: أَخَذَ بِنَفْسِي الَّذِي أَخَذَ بِنَفْسِكَ، بِأَبِي أَنْتَ وَأُمِّي يَا رَسُولَ اللهِ! قَالَ: "اقْتَادُوا" فَاقْتَادُوا رَوَاحِلَهُمْ شَيْئًا، ثُمَّ تَوَضَّأَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَمَرَ بِلَالًا، فَأَقَامَ الصَّلَاةَ، فَصَلَّى بِهِمُ الصُّبْحَ، فَلَمَّا قَضَى الصَّلَاةَ قَالَ: "مَنْ نَسِيَ الصَّلَاةَ فَلْيُصَلِّهَا إِذَا ذَكَرَهَا، فَإِنَّ اللهَ قَالَ { أَقِمِ الصَّلَاةَ لِذِكْرِي} [طه:١٤]. (ق,د,ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) ഖൈബർ യുദ്ധം കഴിഞ്ഞ് രാത്രി മടങ്ങിവരുമ്പോൾ ഉറക്കം വരികയും വിശ്രമത്തിനായി ഒരിടത്ത് ഇറങ്ങുകയും ചെയ്തു. ബിലാലിനോട് പറഞ്ഞു: "ബിലാൽ! നീ ഞങ്ങൾക്ക് രാത്രിയിലെ കാവൽക്കാരനാകുക." ബിലാൽ കഴിയുന്നത്ര നിസ്കരിച്ചുകൊണ്ടിരുന്നു. നബി(സ)യും സഹാബികളും ഉറങ്ങി. പ്രഭാതമാവാറായപ്പോൾ ബിലാൽ പ്രഭാതവും പ്രതീക്ഷിച്ച് വാഹനത്തിൽ ചാരി ഇരുന്നു. ബിലാൽ ഉറങ്ങിപ്പോയി. സൂര്യന്റെ വെയിൽ തട്ടുന്നതുവരെ ബിലാലോ സഹാബികളോ ഉണർന്നില്ല. പ്രവാചകനായിരുന്നു ഒന്നാമനായി ഉണർന്നത്. റസൂൽ അസ്വസ്ഥനായി ബിലാലിനെ വിളിച്ചു. ബിലാൽ പറഞ്ഞു: എന്റെ മാതാപിതാക്കൾ അങ്ങേക്ക് ദണ്ഡം, എല്ലാമായ പ്രവാചകരേ! താങ്കളെ ഉറക്കിയവൻ എന്നെയും ഉറക്കി. നബി(സ) പറഞ്ഞു: "മൃഗങ്ങളെ തെളിക്കൂ! അവർ അൽപം മുന്നോട്ട് തെളിച്ചു." പിന്നെ നബി(സ) വുദു ചെയ്ത് ബിലാലിനോട് ഇഖാമത്ത് വിളിക്കാൻ നിർദ്ദേശിച്ചു. നബി(സ) അവരോടോപ്പം സുബ്ഹ് നിസ്കരിച്ചു. നിസ്കാരം കഴിഞ്ഞപ്പോൾ നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും നിസ്കരിക്കാൻ മറന്നാൽ ഓർമ്മ വന്നയുടൻ നിസ്കരിക്കട്ടെ". അല്ലാഹു പറഞ്ഞു: "എന്റെ സ്മരണക്കു വേണ്ടി നിസ്കാരം നിലനിർത്തുക." (ബു,മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], 'طه:١٤', null, 341, 341, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَ سَلَّمَ: "تَحَوَّلُوا عَنْ مَكَانِكُمُ الَّذِي أَصَابَتْكُمْ فِيهِ الْغَفْلَةُ". فَأَمَرَ بِلَالًا فَأَذَّنَ وَأَقَامَ وَصَلَّى. (د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾക്ക് (നിസ്കാരത്തിൽ) അശ്രദ്ധ ബാധിച്ച സ്ഥലത്തുനിന്ന് നീങ്ങുക." പിന്നെ ബിലാലിനോട് ബാങ്കു വിളിക്കാൻ കൽപിക്കുകയും ബാങ്കും ഇഖാമത്തും വിളിച്ച് നിസ്കരിക്കുകയും ചെയ്തു. (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 341, 341, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: عَرَّسْنَا مَعَ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمْ نَسْتَيْقِظْ حَتَّى طَلَعَتِ الشَّمْسُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لِيَأْخُذْ كُلُّ رَجُلٍ بِرَأْسِ رَاحِلَتِهِ، فَإِنَّ هَذَا مَنْزِلٌ حَضَرَنَا فِيهِ الشَّيْطَانُ". قَالَ: فَفَعَلْنَا، فَدَعَا بِالْمَاءِ، فَتَوَضَّأَ، ثُمَّ صَلَّى سَجْدَتَيْنِ، ثُمَّ أُقِيمَتِ الصَّلَاةُ، فَصَلَّى الْغَدَاةَ. (م,ن)', 'അബൂഹുറൈറ(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പം രാത്രി കഴിച്ചുകൂട്ടി. സൂര്യൻ ഉദിക്കുംവരെ ഞങ്ങൾ ഉണർന്നില്ല. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഓരോരുത്തരും വാഹനത്തിന്റെ മൂക്കുകയർ പിടിക്കട്ടെ. നാം ഈ നിൽക്കുന്ന സ്ഥലം പിശാച് നമ്മുടെയടുത്ത് വന്നതാണ്." അബൂഹുറൈറ(റ) പറഞ്ഞു: ഞങ്ങൾ അപ്രകാരം ചെയ്തു. അൽപം മുന്നോട്ട് നീങ്ങി പിന്നെ നബി(സ) വെള്ളത്തിന് ആവശ്യപ്പെടുകയും വുളു ചെയ്ത് രണ്ട് റക്അത്ത് നിസ്കരിക്കുകയും ചെയ്തു. ഇഖാമത്ത് വിളിച്ച ശേഷം പ്രഭാത നിസ്കാരം നിർവ്വഹിച്ചു. (മു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 342, 342, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللهُ عَنْهُ قَالَ: ذَكَرُوا تَفْرِيطَهُمْ فِي النَّوْمِ، فَقَالَ: نَامُوا حَتَّى طَلَعَتِ الشَّمْسُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَيْسَ فِي النَّوْمِ تَفْرِيطٌ، إِنَّمَا التَّفْرِيطُ فِي الْيَقَظَةِ، فَإِذَا نَسِيَ أَحَدُكُمْ صَلَاةً أَوْ نَامَ عَنْهَا فَلْيُصَلِّهَا إِذَا ذَكَرَهَا،وَلِوَقْتِهَا مِنَ الْغَدِ". (م,د,ت,ن,جه)', 'അബൂഖതാദ(റ): ഉറക്കം ചുരുക്കുന്നതിനെക്കുറിച്ച് അവർ പറഞ്ഞപ്പോൾ അബൂഖതാദ പറഞ്ഞു: സൂര്യൻ ഉദിക്കുംവരെ അവർ (നബി(സ)യും സ്വഹാബികളും) ഉറങ്ങിപ്പോയി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഉറക്കം കാരണത്താൽ ചുരുക്കാൻ പാടില്ല. ചുരുക്കാവുന്നത് ഉണർച്ചയിലാണ്. ആരെങ്കിലും നിസ്കാരം മറക്കുകയോ ഉറങ്ങുകയോ ചെയ്താൽ അത് ഓർമ്മ വരുമ്പോൾ നിർവ്വഹിക്കട്ടെ. അടുത്ത ദിവസം അതിന്റെ സമയത്തു തന്നെ നിർവ്വഹിക്കാൻ ശ്രദ്ധിക്കട്ടെ." (മു,ദ,തു,ന,ജ)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 342, 342, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سِرْنَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةً، فَقَالَ بَعْضُ الْقَوْمِ: لَوْ عَرَّسْتَ بِنَا يَا رَسُولَ اللهِ! قَالَ : "أَخَافُ أَنْ تَنَامُوا عَنِ الصَّلَاةِ". قَالَ بِلَالٌ: أَنَا أُوقِظُكُمْ، فَاضْطَجَعُوا، وَأَسْنَدَ بِلَالٌ ظَهْرَهُ إِلَى رَاحِلَتِهِ، فَغَلَبَتْهُ عَيْنَاهُ فَنَامَ، فَاسْتَيْقَظَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَقَدْ طَلَعَ حَاجِبُ الشَّمْسِ، فَقَالَ: "يَا بِلَالُ! أَيْنَ مَا قُلْتَ". قَالَ: مَا أُلْقِيتْ عَلَيَّ نَوْمَةٌ مِثْلُهَا قَطُّ، قَالَ: "إِنَّ اللهَ قَبَضَ أَرْوَاحَكُمْ حِينَ شَاءَ، وَرَدَّهَا عَلَيْكُمْ حِينَ شَاءَ، يَا بِلَالُ ! قُمْ فَأَذِّنْ بِالنَّاسِ بِالصَّلَاةِ". فَتَوَضَّأَ، فَلَمَّا ارْتَفَعَتِ الشَّمْسُ وَابْيَضَّتْ قَامَ فَصَلَّى. (خ,ن)', 'അബൂഖതാദ(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പം ഒരു രാത്രിയിൽ യാത്രപോയി. അപ്പോൾ ചിലർ പറഞ്ഞു: നബിയെ, നമുക്കല്പം വിശ്രമിച്ചുകൂടെ? നബി(സ) പറഞ്ഞു: "നിങ്ങൾ നിസ്കരിക്കാതെ ഉറങ്ങിപ്പോകുന്നതിനെ ഞാൻ ഭയപ്പെടുന്നു." ബിലാൽ(റ) പറഞ്ഞു: നിങ്ങളെ ഞാൻ ഉണർത്താം. അങ്ങനെ അവർ കിടന്നു. ബിലാൽ തന്റെ വാഹനത്തിൽ ചാരി ഇരുന്നു. ഉറക്കം അദ്ദേഹത്തിന്റെ കണ്ണുകളെ ബാധിച്ചു. നബി(സ) ഉണർന്നപ്പോൾ സൂര്യൻ പ്രകാശിച്ചു കഴിഞ്ഞിരുന്നു. അപ്പോൾ നബി(സ) ബിലാലിനോട് ചോദിച്ചു: "ബിലാലേ നീ പറഞ്ഞതെവിടെ?" ബിലാൽ(റ) പറഞ്ഞു: ഇതുപോലെ ഒരുറക്കം ഒരിക്കലും സംഭവിച്ചിട്ടില്ല. നബി(സ) പറഞ്ഞു: "അല്ലാഹു അവനുദ്ദേശിക്കുമ്പോൾ നിങ്ങളുടെ ആത്മാവുകളെ പിടികൂടുന്നു. അവനുദ്ദേശിക്കുമ്പോൾ അതു തിരിച്ചു നൽകുന്നു. ബിലാലേ! നീ എഴുന്നേറ്റ് ബാങ്ക് വിളിക്കൂ." നബി(സ) വുദു ചെയ്ത് നിസ്കരിച്ചു. അപ്പോൾ സൂര്യൻ ഉദിച്ചുയർന്നിരുന്നു. (ബു,ന)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 342, 342, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنْ خَالِدِ بْنِ سُمَيْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَدِمَ عَلَيْنَا عَبْدُ اللهِ بْنُ رَبَاحٍ الْأَنْصَارِيُّ مِنَ الْمَدِينَةِ - وَكَانَتِ الْأَنْصَارُ تُفَقِّهُهُ - فَحَدَّثَنَا قَالَ: حَدَّثَنِي أَبُو قَتَادَةَ الْأَنْصَارِيُّ فَارِسُ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: بَعَثَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَيْشَ الْأُمَرَاءِ - بِهَذِهِ الْقِصَّةِ - قَالَ: فَلَمْ تُوقِظْنَا إِلَّا الشَّمْسُ طَالِعَةً، فَقُمْنَا وَهِلِينَ لِصَلَاتِنَا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "رُوَيْدًا رُوَيْدًا" حَتَّى إِذَا تَعَالَتِ الشَّمْسُ: قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ كَانَ مِنْكُمْ يَرْكَعُ رَكْعَتَيِ الْفَجْرِ فَلْيَرْكَعْهُمَا" فَقَامَ مَنْ كَانَ يَرْكَعُهُمَا وَمَنْ لَمْ يَكُنْ يَرْكَعُهُمَا فَرَكَعَهُمَا، ثُمَّ أَمَرَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُنَادَى بِالصَّلَاةِ، فَنُودِيَ بِهَا، فَقَامَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَصَلَّى بِنَا، فَلَمَّا انْصَرَفَ قَالَ: "أَلَا إِنَّا نَحْمَدُ اللهَ، أَنَّا لَمْ نَكُنْ فِي شَيْءٍ مِنْ أُمُورِ الدُّنْيَا يَشْغَلُنَا عَنْ صَلَاتِنَا، وَلَكِنَّ أَرْوَاحَنَا كَانَتْ بِيَدِ اللهِ عَزَّ وَجَلَّ، فَأَرْسَلَهَا أَنَّى شَاءَ، فَمَنْ أَدْرَكَ مِنْكُمْ صَلَاةَ الْغَدَاةِ مِنْ غَدٍ صَالِحًا فَلْيَقْضِ مَعَهَا مِثْلَهَا". (د)', 'ഖാലിദുബ്നു സൂമൈർ(റ): മദീനയിൽ നിന്നും അബ്ദുല്ലാഹിബ്നു റബാഹ് ഞങ്ങളുടെ അടുത്തേക്ക് വന്നു. അൻസാറുകൾ അദ്ദേഹത്തെ ഫഖീഹ്¹⁰ ആയി പരിഗണിച്ചിരുന്നു. അദ്ദേഹം പറഞ്ഞു: നബി(സ) നേതാക്കളുടെ ഒരു സൈന്യത്തെ അയച്ച സംഭവം വിവരിച്ചുകൊണ്ട് നബിയുടെ കുതിരപ്പടയാളിയായ അബഖതാദ(റ) എന്നോട് പറഞ്ഞിട്ടുണ്ട്: ഉദയ സൂര്യനാണ് ഞങ്ങളെ ഉണർത്തിയത്. ഞങ്ങൾ നിസ്കാരത്തിന് വിഭ്രാന്തി കാണിച്ചു. നബി(സ) പറഞ്ഞു: "സാവകാശം! സാവകാശം!" സൂര്യൻ ഉയർന്നപ്പോൾ നബി(സ) പറഞ്ഞു: "ഫജ്റിന്റെ രണ്ട് റക്അത്ത് നിസ്കരിക്കുന്നവൻ നിസ്കരിച്ചു കൊള്ളുക." നിസ്കരിക്കാൻ ഉദ്ദേശിച്ചവരും അല്ലാത്തവരും അത് നിർവ്വഹിച്ചു. പിന്നെ നിസ്കാരത്തിന് വിളിക്കാൻ കൽപിച്ചു. നബി(സ) എഴുന്നേറ്റ് ഞങ്ങളോടൊപ്പം നിസ്കരിച്ചു. പിരിഞ്ഞപ്പോൾ ഇപ്രകാരം പറഞ്ഞു: "നാം അല്ലാഹുവിനെ സ്തുതിക്കുന്നു,. ഐഹികമായ ഒരു കാര്യവുമല്ല നമ്മെ നിസ്കാരത്തിൽ നിന്ന് ശ്രദ്ധ തെറ്റിച്ചത്. എന്നാൽ നമ്മുടെ ആത്മാക്കൾ അല്ലാഹുവിന്റെ കൈകളിലാണ്. അവനുദ്ദേശിക്കുമ്പോൾ അതിനെ അയക്കുന്നു. അതിനാൽ നാളെ പ്രഭാതനിസ്കാരം നല്ല നിലയിൽ ലഭിക്കുന്നവരൊക്കെ അതിനോടൊപ്പം അതുപോലെ ഒന്നുകൂടെ നിർവ്വഹിക്കട്ടെ!" (ദ)', 'خَالِدِ بْنِ سُمَيْرٍ', 'ഖാലിദുബ്നു സൂമൈർ(റ)', '¹⁰. മതവിഷയങ്ങളിൽ അവഗാഹമുള്ളവൻ', null, array['د']::text[], array['ദ']::text[], null, null, 342, 343, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ ذِي مِخْبَرٍ الْحَبَشِيِّ رَضِيَ اللهُ عَنْهُ - وَكَانَ يَخْدُمُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَ: فَتَوَضَّأَ يَعْنِي النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وُضُوءًا، لَمْ يَلْثَ مِنْهُ التُّرَابُ، ثُمَّ أَمَرَ بِلَالًا فَأَذَّنَ، ثُمَّ قَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرَكَعَ رَكْعَتَيْنِ غَيْرَ عَجِلٍ، ثُمَّ قَالَ لِبِلَالٍ: "أَقِمِ الصَّلَاةَ". ثُمَّ صَلَّى الْفَرْضَ وَهُوَ غَيْرُ عَجِلٍ. (د)', 'നബി(സ)ക്ക് സേവനം ചെയ്തിരുന്ന ദൂ മിഖ്ബറിൽ ഹബ്ശി(റ): നബി(സ) വുളു ചെയ്തു. നബിയിൽനിന്ന് പൊടിമണ്ണ് നീങ്ങിപ്പോയിരുന്നില്ല. പിന്നെ ബിലാലിനോട് ബാങ്ക് വിളിക്കാൻ കൽപ്പിച്ചപ്പോൾ ബിലാൽ ബാങ്ക് വിളിച്ചു. നബി(സ) എഴുന്നേറ്റ് സാവകാശം രണ്ട് റക്അത്ത് നിർവ്വഹിച്ചു. ബിലാലിനോട് ഇഖാമത്ത് വിളിക്കാനാവശ്യപ്പെടുകയും ധൃതിപ്പെടാതെ തന്നെ നിർബന്ധ നിസ്കാരം നിർവ്വഹിക്കുകയും ചെയ്തു. (ദ)', 'ذِي مِخْبَرٍ الْحَبَشِيِّ', 'നബി(സ)ക്ക് സേവനം ചെയ്തിരുന്ന ദൂ മിഖ്ബറിൽ ഹബ്ശി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 343, 343, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَقْبَلْنَا مَعَ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ زَمَنَ الْحُدَيْبِيَةِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ يَكْلَؤُنَا". فَقَالَ بِلَالٌ: أَنَا، فَنَامُوا حَتَّى طَلَعَتِ الشَّمْسُ، فَاسْتَيْقَظَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "افْعَلُوا كَمَا كُنْتُمْ تَفْعَلُونَ". قَالَ: فَفَعَلْنَا، قَالَ: "فَكَذَلِكَ فَافْعَلُوا لِمَنْ نَامَ أَوْ نَسِيَ". (د,ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ഹുദൈബിയ്യയുടെ സമയത്ത് ഞങ്ങൾ നബി(സ)യോടൊപ്പം പുറപ്പെട്ടു. അപ്പോൾ നബി(സ) ചോദിച്ചു. "ആരാണ് കാവൽ നിൽക്കുക?" ബിലാൽ പറഞ്ഞു: ഞാൻ. അങ്ങനെ സൂര്യൻ ഉദിക്കുംവരെ അവർ ഉറങ്ങി. നബി(സ) ഉണർന്നശേഷം പറഞ്ഞു: "നിങ്ങൾ ചെയ്യാറുള്ള പ്രകാരം ചെയ്യുക. ഞങ്ങൾ അങ്ങനെ ചെയ്തു. നബി(സ) പറഞ്ഞു: " ഉറങ്ങിയവനും മറന്നവനും ഇപ്രകാരമാണ് ചെയ്യേണ്ടത്." (ദ,ന)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 343, 343, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَدْلَجَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ عَرَّسَ، فَلَمْ يَسْتَيْقِظْ حَتَّى طَلَعَتِ الشَّمْسُ أَوْ بَعْضُهَا، فَلَمْ يُصَلِّ حَتَّى ارْتَفَعَتِ الشَّمْسُ، فَصَلَّى وَهِيَ صَلَاةُ الْوُسْطَى (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) രാത്രികാല യാത്രയിൽ വിശ്രമത്തിലേർപ്പെട്ടു. സൂര്യൻ പാതി, അല്ലെങ്കിൽ പൂർണ്ണമായോ ഉദിക്കും വരെ തിരുമേനി(സ) ഉണർന്നില്ല. സൂര്യൻ ഉദിച്ചുയരും വരെ നിസ്കരിച്ചില്ല. ശേഷം നിസ്കരിച്ചു അത് മധ്യ നിസ്കാരമായിരുന്നു. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 344, 344, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنَّا مَعَ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَحُبِسْنَا عَنْ صَلَاةِ الظُّهْرِ وَالْعَصْرِ وَالْمَغْرِبِ وَالْعِشَاءِ، فَاشْتَدَّ ذَلِكَ عَلَيَّ، فَقُلْتُ فِي نَفْسِي: نَحْنُ مَعَ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَفِي سَبِيلِ اللهِ، فَأَمَرَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِلَالًا فَأَقَامَ، فَصَلَّى بِنَا الظُّهْرَ، ثُمَّ أَقَامَ فَصَلَّى بِنَا الْعَصْرَ، ثُمَّ أَقَامَ فَصَلَّى بِنَا الْمَغْرِبَ، ثُمَّ أَقَامَ فَصَلَّى بِنَا الْعِشَاءَ، ثُمَّ طَافَ عَلَيْنَا فَقَالَ، "مَا عَلَى الْأَرْضِ عِصَابَةٌ يَذْكُرُونَ اللهَ عَزَّ وَجَلَّ غَيْرُكُمْ" (ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പമായിരിക്കെ ഞങ്ങൾക്ക് ളുഹ്ർ, അസ്ർ, മഗ്രിബ്, ഇശാ എന്നീ നിസ്കാരങ്ങൾ തടയപ്പെട്ടു. അതെനിക്ക് ഏറെ പ്രയാസകരമായി അനുഭവപ്പെട്ടു. ഞാൻ ഇങ്ങനെ ആത്മഗതം ചെയ്തു: ''ഞങ്ങൾ നബി(സ)യോടൊപ്പമാണ്. അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലുമാണ്''. നബി(സ) ബിലാലിനോട് ഇഖാമത്ത് വിളിക്കാൻ കൽപ്പിച്ചു. ബിലാൽ(റ) ഇഖാമത്ത് വിളിച്ചു. ഞങ്ങളോടൊപ്പം ളുഹ്ർ നിസ്കരിച്ചു, പിന്നെ ഇഖാമത്ത് വിളിച്ച് അസ്ർ നിസ്കരിച്ചു, പിന്നെ ഇഖാമത്ത് വിളിച്ച് മഗ്രിബ് നിസ്കരിച്ചു, പിന്നെ ഇഖാമത്ത് വിളിച്ച് ഇശാ നിസ്കരിച്ചു. ഞങ്ങൾക്കു ചുറ്റും നടന്നുകൊണ്ട് നബി(സ) പറഞ്ഞു: "ഭൂമിയിൽ നിങ്ങളല്ലാതെ അല്ലാഹുവിനെ സ്മരിച്ചുകൊണ്ടിരിക്കുന്ന ഒരു സംഘവുമില്ല." (ന)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 344, 344, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
